            terminal_metadata["terminal_retry_rejected_reason"] = rejected_retry_reason
            terminal_metadata["retry_command"] = high_signal_retry_command
            terminal_metadata["retry_rejected_reason"] = high_signal_retry_reason
            rejected_retry_command = high_signal_retry_command
            rejected_retry_reason = high_signal_retry_reason
