    def _artifact_behavior_target_body_timeout_context_read_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        if not self._artifact_policy_timeout_error(error_text):
            return None
        if any(
            str(step.decision_source).strip() == "artifact_behavior_target_body_timeout_context_read"
            for step in state.history
        ):
            return None
        target_step = None
        for step in reversed(state.history):
            if str(step.decision_source).strip() in {
                "artifact_behavior_target_body_retry_failed_context_read",
                "artifact_behavior_target_body_retry_context_read",
                "artifact_behavior_target_body_context_read",
            }:
                target_step = step
                break
        if target_step is None:
            return None
        metadata = target_step.proposal_metadata if isinstance(target_step.proposal_metadata, dict) else {}
        path = str(metadata.get("artifact_candidate_path", "")).strip().strip("/")
        raw_spans = metadata.get("operation_spans", [])
        if not path or not isinstance(raw_spans, list):
            return None
        operation_spans = [str(item).strip() for item in raw_spans if str(item).strip()]
        if not operation_spans:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        artifact_path = contract.artifact_path if contract is not None and contract.artifact_path else "patch.diff"
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        allowed_excerpt: list[str] = []
        for item in operation_spans[:2]:
            try:
                start_text, end_text = item.split(":", 1)
                start = int(start_text)
                end = int(end_text)
            except (TypeError, ValueError):
                continue
            for line_number in range(max(1, start - 3), end + 4):
                if line_number in source_by_number:
                    allowed_excerpt.append(f"{line_number}: {source_by_number[line_number]}")
        context = {
            "mode": "behavior_target_body_timeout_compact_retry",
            "artifact_path": artifact_path,
            "path": path,
            "allowed_operation_spans": operation_spans,
            "allowed_source_excerpt": "\n".join(dict.fromkeys(allowed_excerpt))[:1200],
            "timeout_error": str(error_text)[:300],
            "required_next_action": (
                "Previous decision timed out. Emit exactly one command only. No prose. No source inspection. "
                "Use the source path and allowed span below."
            ),
            "valid_command_shape": (
                f"swe_patch_builder --path {path} --replace-lines <allowed_start> <allowed_end> "
                f"--with '<body statement line>' > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Expose compact body-target materialization context after LLM timeout.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_behavior_target_body_timeout_context_read",
            proposal_metadata={
                "artifact_behavior_target_body_timeout_context_read": True,
                "retry_rejected_reason": "behavior_target_body_timeout",
                "artifact_candidate_path": path,
                "operation_spans": operation_spans,
                "error_preview": str(error_text)[:1200],
            },
        )

