    @staticmethod
    def _artifact_behavior_target_enclosing_block_context_read_decision(
        state: AgentState,
        *,
        rejected_command: str,
        rejected_reason: str,
        artifact_path: str,
        retry_attempt: int,
    ) -> ActionDecision | None:
        if any(
            str(step.decision_source).strip() == "artifact_behavior_target_enclosing_block_context_read"
            for step in state.history
        ):
            return None
        target_step = None
        for step in reversed(state.history):
            if str(step.decision_source).strip() in {
                "artifact_behavior_target_body_retry_exhausted_context_read",
                "artifact_behavior_target_statement_kind_failed_context_read",
            }:
                target_step = step
                break
        if target_step is None:
            return None
        metadata = target_step.proposal_metadata if isinstance(target_step.proposal_metadata, dict) else {}
        path = str(metadata.get("artifact_candidate_path", "")).strip().strip("/")
        raw_spans = metadata.get("operation_spans", [])
        if not path or not isinstance(raw_spans, list):
            return None
        operation_spans = [str(item).strip() for item in raw_spans if str(item).strip()]
        if not operation_spans:
            return None
        try:
            target_start = int(operation_spans[0].split(":", 1)[0])
            target_end = int(operation_spans[0].split(":", 1)[1])
        except (IndexError, ValueError):
            return None
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        if target_start not in source_by_number:
            return None
        target_line = str(source_by_number.get(target_start, ""))
        target_stripped = target_line.lstrip()
        target_indent = len(target_line) - len(target_stripped)
        block_start = target_start
        block_indent = target_indent
        header_line = 0
        for line_number in range(target_start - 1, 0, -1):
            line = str(source_by_number.get(line_number, ""))
            if not line.strip():
                continue
            stripped = line.lstrip()
            indent = len(line) - len(stripped)
            if indent < target_indent and (
                stripped.startswith("def ")
                or stripped.startswith("async def ")
                or stripped.startswith("class ")
            ):
                header_line = line_number
                block_start = line_number + 1
                block_indent = target_indent
                break
            if indent < target_indent and stripped.endswith(":"):
                block_start = line_number
                block_indent = indent
                break
            if indent < target_indent and header_line == 0:
                block_start = line_number + 1
                block_indent = target_indent
                break
        block_end = target_end
        max_line = max(source_by_number) if source_by_number else target_end
        for line_number in range(target_end + 1, max_line + 1):
            line = str(source_by_number.get(line_number, ""))
            if not line.strip():
                continue
            stripped = line.lstrip()
            indent = len(line) - len(stripped)
            if indent < block_indent or (
                header_line > 0
                and indent == 0
                and (stripped.startswith("def ") or stripped.startswith("async def ") or stripped.startswith("class "))
            ):
                break
            block_end = line_number
        if block_start > target_start:
            block_start = target_start
        if block_end < target_end:
            block_end = target_end
        if block_end - block_start > 40:
            block_start = max(block_start, target_start - 12)
            block_end = min(block_end, target_end + 20)
        if block_start == target_start and block_end == target_end:
            return None
        excerpt = []
        for line_number in range(block_start, block_end + 1):
            if line_number in source_by_number:
                excerpt.append(f"{line_number}: {source_by_number[line_number]}")
        context = {
            "mode": "behavior_target_enclosing_block_repair",
            "artifact_path": artifact_path,
            "path": path,
            "rejected_command": str(rejected_command)[:1500],
            "rejected_reason": str(rejected_reason)[:300],
            "previous_allowed_operation_spans": operation_spans,
            "allowed_operation_spans": [f"{block_start}:{block_end}"],
            "target_operation_spans": operation_spans,
            "allowed_source_excerpt": "\n".join(excerpt)[:3500],
            "required_next_action": (
                "The one-line body target exhausted without materializing. Escalate only to this enclosing "
                "body/block span. Do not edit declaration headers, do not inspect source, and do not use "
                "patch.diff as the source path."
            ),
            "forbidden_patterns": [
                "--source",
                "--path patch.diff",
                "cat<space>",
                "sed<space>",
                "head<space>",
                "tail<space>",
                "def<space>",
                "class<space>",
            ],
            "valid_command_shape": (
                f"swe_patch_builder --path {path} --replace-lines <allowed_start> <allowed_end> "
                f"--with '<body statement line>' [--with '<body statement line>'] > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Escalate exhausted one-line behavior target to its enclosing executable block span.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_behavior_target_enclosing_block_context_read",
            proposal_metadata={
                "artifact_behavior_target_enclosing_block_context_read": True,
                "artifact_materialization_retry_attempt": retry_attempt,
                "retry_command": rejected_command,
                "retry_rejected_reason": "behavior_target_enclosing_block_repair",
                "artifact_candidate_path": path,
                "operation_spans": [f"{block_start}:{block_end}"],
                "target_operation_spans": operation_spans,
            },
        )

