    @staticmethod
    def _artifact_behavior_target_statement_kind_context_read_decision(
        state: AgentState,
        *,
        rejected_command: str,
        rejected_reason: str,
        artifact_path: str,
        retry_attempt: int,
    ) -> ActionDecision | None:
        if str(rejected_reason).strip() != "statement_kind_replacement":
            return None
        if any(
            str(step.decision_source).strip() == "artifact_behavior_target_statement_kind_context_read"
            for step in state.history
        ):
            return None
        target_step = None
        for step in reversed(state.history):
            if str(step.decision_source).strip() in {
                "artifact_behavior_target_body_timeout_failed_context_read",
                "artifact_behavior_target_body_timeout_context_read",
                "artifact_behavior_target_body_retry_failed_context_read",
                "artifact_behavior_target_body_retry_context_read",
                "artifact_behavior_target_body_context_read",
            }:
                target_step = step
                break
        if target_step is None:
            return None
        metadata = target_step.proposal_metadata if isinstance(target_step.proposal_metadata, dict) else {}
        path = str(metadata.get("artifact_candidate_path", "")).strip().strip("/")
        raw_spans = metadata.get("operation_spans", [])
        if not path or not isinstance(raw_spans, list):
            return None
        operation_spans = [str(item).strip() for item in raw_spans if str(item).strip()]
        if not operation_spans:
            return None
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        fail_to_pass_body_lines = LLMDecisionPolicy._artifact_fail_to_pass_body_line_numbers(state, path)
        fail_to_pass_body_set = set(fail_to_pass_body_lines)
        span_overlaps_executable_body = False
        for item in operation_spans:
            try:
                start_text, end_text = item.split(":", 1)
                start = int(start_text)
                end = int(end_text)
            except (TypeError, ValueError):
                continue
            if any(start <= line_number <= end for line_number in fail_to_pass_body_set):
                span_overlaps_executable_body = True
                break
        if fail_to_pass_body_lines and not span_overlaps_executable_body:
            operation_spans = [f"{line_number}:{line_number}" for line_number in fail_to_pass_body_lines[:12]]
        source_lines: list[str] = []
        required_prefixes: set[str] = set()
        for item in operation_spans:
            try:
                start_text, end_text = item.split(":", 1)
                start = int(start_text)
                end = int(end_text)
            except (TypeError, ValueError):
                continue
            for line_number in range(start, end + 1):
                line = str(source_by_number.get(line_number, ""))
                if not line:
                    continue
                source_lines.append(f"{line_number}: {line}")
                stripped = line.lstrip()
                indent = line[: len(line) - len(stripped)]
                if stripped.startswith("return "):
                    required_prefixes.add(f"{indent}return ")
                elif stripped.startswith("raise "):
                    required_prefixes.add(f"{indent}raise ")
                elif stripped.startswith("yield "):
                    required_prefixes.add(f"{indent}yield ")
        context = {
            "mode": "behavior_target_statement_kind_repair",
            "artifact_path": artifact_path,
            "path": path,
            "rejected_command": str(rejected_command)[:1500],
            "rejected_reason": str(rejected_reason)[:300],
            "allowed_operation_spans": operation_spans,
            "target_source_lines": "\n".join(source_lines)[:1200],
            "required_replacement_prefixes": sorted(required_prefixes),
            "required_next_action": (
                "The replacement changed the statement kind. Preserve the target statement kind and indentation. "
                "For a return line, replacement lines must also begin with the required return prefix."
            ),
            "valid_command_shape": (
                f"swe_patch_builder --path {path} --replace-lines <allowed_start> <allowed_end> "
                f"--with '<same-kind body statement>' > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Expose statement-kind repair context for behavior-target body replacement.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_behavior_target_statement_kind_context_read",
            proposal_metadata={
                "artifact_behavior_target_statement_kind_context_read": True,
                "artifact_materialization_retry_attempt": retry_attempt,
                "retry_command": rejected_command,
                "retry_rejected_reason": "behavior_target_statement_kind_repair",
                "artifact_candidate_path": path,
                "operation_spans": operation_spans,
            },
        )

