    def _artifact_shallow_repeat_timeout_context_read_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        recent_sources = [str(step.decision_source).strip() for step in state.history[-6:]]
        if "artifact_shallow_patch_context_read" not in recent_sources:
            return None
        if "artifact_source_inspection_repeat_blocked_context_read" not in recent_sources:
            return None
        if any(
            str(step.decision_source).strip() == "artifact_shallow_repeat_timeout_context_read"
            for step in state.history[-8:]
        ):
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        if not path:
            return None
        shallow_metadata: dict[str, object] = {}
        shallow_content = ""
        for step in reversed(state.history):
            if str(step.decision_source).strip() == "artifact_shallow_patch_context_read":
                shallow_metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
                shallow_content = str(step.content)
                break
        candidate_records = [
            self._artifact_virtual_candidate_context_record(record)
            for record in self._artifact_placeholder_safe_candidate_records(
                list(artifact_repair_context.get("candidate_edit_records", []) or [])
            )[:6]
            if isinstance(record, dict)
        ]
        context = {
            "mode": "shallow_repeat_timeout_compact_repair",
            "artifact_path": artifact_path,
            "builder_command": builder_command,
            "path": path,
            "prior_shallow_command": str(shallow_metadata.get("retry_command", ""))[:700],
            "candidate_edit_records": candidate_records,
            "source_lines_excerpt": str(artifact_repair_context.get("source_lines_excerpt", ""))[:1200],
            "shallow_context_excerpt": shallow_content[:1200],
            "timeout_error": str(error_text)[:300],
            "required_next_action": (
                "Do not inspect source again. The prior one-line edit was too shallow. Emit one compact "
                "builder command that uses --replace-lines on the smallest complete statement/control-flow "
                "range near the rejected edit, preserving surrounding syntax."
            ),
            "valid_command_shape": (
                f"{builder_command} --path {path} --replace-lines <start> <end> "
                f"--with '<line1>' [--with '<line2>' ...] > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Expose ultra-compact shallow-repeat timeout repair context.",
            action=CODE_EXECUTE,
            content=self._artifact_virtual_context_noop_command(json.dumps(context, indent=2, sort_keys=True)),
            done=False,
            decision_source="artifact_shallow_repeat_timeout_context_read",
            proposal_metadata={
                "artifact_shallow_repeat_timeout_context_read": True,
                "artifact_candidate_path": path,
                "artifact_diagnostic_context_count": self._artifact_recent_diagnostic_context_count(state),
                "error_preview": str(error_text)[:1200],
                "retry_rejected_reason": "shallow_repeat_policy_timeout",
            },
        )

