    def _artifact_function_body_strict_index_direct_decision(self, state: AgentState) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        recent_sources = [str(step.decision_source).strip() for step in state.history[-10:]]
        trigger_sources = {
            "artifact_definition_header_body_pre_context_read",
            "artifact_definition_header_body_failed_context_read",
            "artifact_invalid_python_off_target_context_read",
            "artifact_candidate_cluster_reanchor_context_read",
            "artifact_candidate_cluster_reanchor_failed_context_read",
        }
        if not any(source in trigger_sources for source in recent_sources):
            return None
        if "artifact_function_body_strict_index_direct" in recent_sources:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        path = ""
        for step in reversed(state.history[-10:]):
            metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
            candidate_path = str(metadata.get("artifact_candidate_path", "")).strip().strip("/")
            if candidate_path:
                path = candidate_path
                break
        if not path:
            artifact_repair_context = self._artifact_retry_context_payload(
                state,
                artifact_path=artifact_path,
                builder_command=builder_command,
            )
            path = str(artifact_repair_context.get("preferred_source_path", "")).strip().strip("/")
        if not path or not path.endswith(".py"):
            return None
        source_by_number = self._artifact_source_lines_by_number(state, path)
        if not source_by_number:
            return None
        for line_number in self._artifact_fail_to_pass_body_line_numbers(state, path):
            current_source = str(source_by_number.get(int(line_number), "")).rstrip()
            match = re.match(
                r"^(?P<indent>\s*)(?P<target>[A-Za-z_][A-Za-z0-9_]*)\s*=\s*"
                r"(?P<receiver>[A-Za-z_][A-Za-z0-9_]*)\.index\((?P<args>[^)]{1,120})\)"
                r"(?P<trailing>\s*(?:#.*)?)$",
                current_source,
            )
            if match is None:
                continue
            replacement = (
                f"{match.group('indent')}{match.group('target')} = "
                f"{match.group('receiver')}.find({match.group('args')}){match.group('trailing')}"
            )
            if replacement.rstrip() == current_source.rstrip():
                continue
            command = (
                f"{builder_command} --path {shlex.quote(path)} --replace-line {int(line_number)} "
                f"--with {shlex.quote(replacement)} > {artifact_path}"
            )
            if _canonicalize_command(command) in state.all_failed_command_signatures():
                continue
            if self._artifact_builder_guard_rejection_reason(state, command):
                continue
            return ActionDecision(
                thought=(
                    "Promote a fail-to-pass body anchor by replacing a strict string index lookup with a tolerant "
                    "find lookup after header/off-target repair failures."
                ),
                action=CODE_EXECUTE,
                content=command,
                done=False,
                decision_source="artifact_function_body_strict_index_direct",
                proposal_metadata={
                    "artifact_function_body_strict_index_direct": True,
                    "artifact_candidate_path": path,
                    "artifact_anchor_line": int(line_number),
                    "original_source": current_source,
                    "replacement_source": replacement,
                },
            )
        return None

