    def _artifact_definition_header_body_pre_context_decision(self, state: AgentState) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        if "semantic_contract_violation" in list(
            self._artifact_action_failure_memory(state).get("blocked_action_classes", []) or []
        ):
            return None
        if any(
            str(step.decision_source).strip()
            in {
                "artifact_definition_header_body_context_read",
                "artifact_definition_header_body_pre_context_read",
            }
            for step in state.history[-8:]
        ):
            return None
        target_step = None
        for step in reversed(state.history[-6:]):
            if str(step.decision_source).strip() == "artifact_definition_header_context_read":
                target_step = step
                break
        if target_step is None:
            return None
        metadata = target_step.proposal_metadata if isinstance(target_step.proposal_metadata, dict) else {}
        if str(metadata.get("retry_rejected_reason", "")).strip() != "definition_header_removal":
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        decision = self._artifact_definition_header_body_context_read_decision(
            state,
            rejected_command=str(target_step.content),
            rejected_reason="definition_header_removal",
            artifact_path=artifact_path,
            retry_attempt=int(metadata.get("artifact_materialization_retry_attempt", 0) or 0),
        )
        if decision is None:
            return None
        decision.decision_source = "artifact_definition_header_body_pre_context_read"
        decision.proposal_metadata = {
            **dict(decision.proposal_metadata or {}),
            "artifact_definition_header_body_pre_context_read": True,
        }
        return decision

    def _artifact_invalid_python_diagnostic_escape_decision(self, state: AgentState) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        diagnostic_count = self._artifact_recent_diagnostic_context_count(state)
        off_target_context_count = sum(
            1
            for step in state.history[-10:]
            if str(step.decision_source).strip() == "artifact_invalid_python_off_target_context_read"
        )
        if off_target_context_count >= 2:
            contract = artifact_repair_contracts.contract_from_state(state)
            artifact_path = contract.artifact_path if contract is not None and contract.artifact_path else "patch.diff"
            latest_path = artifact_path
            for step in reversed(state.history[-10:]):
                if str(step.decision_source).strip() != "artifact_invalid_python_off_target_context_read":
                    continue
                metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
                latest_path = str(metadata.get("artifact_candidate_path", "")).strip() or latest_path
                break
            return ActionDecision(
                thought=(
                    "Stop artifact repair after repeated off-target invalid-Python diagnostics instead of "
                    "continuing to spend attempts on unrelated source spans."
                ),
                action="respond",
                content=(
                    "Stopping because invalid-Python artifact repair repeatedly targeted source outside the "
                    f"fail-to-pass function for {latest_path}."
                ),
                done=True,
                decision_source="artifact_materialization_guard",
                proposal_metadata={
                    "artifact_invalid_python_off_target_terminal": True,
                    "artifact_candidate_path": latest_path,
                    "artifact_diagnostic_context_count": diagnostic_count,
                    "retry_rejected_reason": "invalid_python_off_target_repeated",
                },
            )
        if diagnostic_count < 3:
            return None
        if not any(
            str(step.decision_source).strip() == "artifact_invalid_python_statement_context_read"
            for step in state.history[-4:]
        ):
            return None
        invalid_python_context_count = sum(
            1
            for step in state.history[-6:]
            if str(step.decision_source).strip() == "artifact_invalid_python_statement_context_read"
        )
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        candidate_records = self._artifact_placeholder_safe_candidate_records(
            list(artifact_repair_context.get("candidate_edit_records", []) or [])
        )
        recent_retry_reasons = {
            str((step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}).get("retry_rejected_reason", "")).strip()
            for step in state.history[-8:]
        }
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        official_feedback = metadata.get("swe_official_feedback", {})
        artifact_failure = (
            official_feedback.get("artifact_contract_failure", {})
            if isinstance(official_feedback, dict)
            else {}
        )
        allow_invalid_python_contract_candidate = (
            isinstance(artifact_failure, dict)
            and str(artifact_failure.get("mode", "")).strip() == "artifact_invalid_python_replacement"
        )
        if path and candidate_records and "definition_header_removal" in recent_retry_reasons:
            command = self._artifact_first_candidate_suggested_replacement_command(
                state,
                candidate_records=candidate_records,
                path=path,
                artifact_path=artifact_path,
                builder_command=builder_command,
            )
            if command:
                return ActionDecision(
                    thought="Recover from exhausted definition-header diagnostics with a guarded body-line candidate.",
                    action=CODE_EXECUTE,
                    content=command,
                    done=False,
                    decision_source="artifact_exhausted_definition_header_candidate_direct",
                    proposal_metadata={
                        "artifact_exhausted_definition_header_candidate": True,
                        "artifact_candidate_path": path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                        "retry_rejected_reason": "definition_header_removal",
                    },
                )
        if (
            path
            and candidate_records
            and (
                (allow_invalid_python_contract_candidate and invalid_python_context_count >= 2)
                or not self._artifact_candidate_suggestions_suppressed_by_feedback(state)
            )
        ):
            command = self._artifact_first_candidate_suggested_replacement_command(
                state,
                candidate_records=candidate_records,
                path=path,
                artifact_path=artifact_path,
                builder_command=builder_command,
            )
            if command:
                return ActionDecision(
                    thought="Recover from invalid Python diagnostics with a guarded source-grounded candidate.",
                    action=CODE_EXECUTE,
                    content=command,
                    done=False,
                    decision_source="artifact_invalid_python_candidate_suggestion_direct",
                    proposal_metadata={
                        "artifact_invalid_python_candidate_suggestion": True,
                        "artifact_candidate_path": path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                    },
                )
        if state.history and str(state.history[-1].decision_source).strip() == "artifact_invalid_python_statement_range_direct":
            # The direct statement-range expansion is an executable repair
            # attempt. If it fails semantically, let the normal artifact
            # materialization/no-op guards classify that result instead of
            # collapsing back into invalid-Python diagnostic exhaustion.
            return None
        recent_invalid_python_operations = self._artifact_recent_invalid_python_repair_operations(state)
        if recent_invalid_python_operations and not any(
            isinstance(step.proposal_metadata, dict)
            and step.proposal_metadata.get("artifact_invalid_python_terminal_statement_range_recovery")
            for step in state.history[-8:]
        ):
            latest_command = ""
            for step in reversed(state.history[-6:]):
                if step.action != CODE_EXECUTE:
                    continue
                if self._artifact_materializes(state, str(step.content)):
                    latest_command = str(step.content)
                    break
            context = {
                "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                "forbidden_retry_command": latest_command,
                "forbidden_retry_reason": (
                    "Invalid-Python diagnostics already identified a complete statement range. Do not retry a "
                    "one-line repair; use the exact suggested_statement_range with --replace-lines."
                ),
                "required_command_shape": (
                    f"{builder_command} --path <path> --replace-lines <start> <end> "
                    f"--with '<line1>' [--with '<line2>' ...] > {artifact_path}"
                ),
                "fail_to_pass_test_source_excerpts": self._artifact_fail_to_pass_test_source_excerpts(state),
            }
            return ActionDecision(
                thought="Re-lock invalid-Python terminal recovery to the known statement-range repair context.",
                action=CODE_EXECUTE,
                content=self._artifact_virtual_context_noop_command(
                    json.dumps(context, indent=2, sort_keys=True)
                ),
                done=False,
                decision_source="artifact_invalid_python_statement_context_read",
                proposal_metadata={
                    "artifact_invalid_python_statement_context_read": True,
                    "artifact_invalid_python_terminal_statement_range_recovery": True,
                    "artifact_materialization_retry_attempt": 0,
                    "artifact_diagnostic_context_count": diagnostic_count,
                    "rejected_command": latest_command,
                    "retry_command": latest_command,
                    "retry_rejected_reason": "invalid_python_replacement",
                    "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                },
            )
        if (
            state.history
            and isinstance(state.history[-1].proposal_metadata, dict)
            and state.history[-1].proposal_metadata.get("artifact_invalid_python_terminal_statement_range_recovery")
        ):
            return None
        if (
            recent_invalid_python_operations
            and state.history
            and str(state.history[-1].decision_source).strip() == "artifact_source_identical_context_read"
            and not any(
                isinstance(step.proposal_metadata, dict)
                and step.proposal_metadata.get("artifact_source_identical_invalid_python_relock")
                for step in state.history[-8:]
            )
        ):
            latest_metadata = state.history[-1].proposal_metadata if isinstance(state.history[-1].proposal_metadata, dict) else {}
            latest_command = str(latest_metadata.get("retry_command", "") or latest_metadata.get("rejected_command", "")).strip()
            context = {
                "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                "forbidden_retry_command": latest_command,
                "forbidden_retry_reason": (
                    "The latest source-identical retry copied one line from inside a prior invalid-Python statement "
                    "range. Do not retry the interior line; use the exact suggested_statement_range with "
                    "--replace-lines and make a behavior-changing replacement."
                ),
                "required_command_shape": (
                    f"{builder_command} --path <path> --replace-lines <start> <end> "
                    f"--with '<line1>' [--with '<line2>' ...] > {artifact_path}"
                ),
                "fail_to_pass_test_source_excerpts": self._artifact_fail_to_pass_test_source_excerpts(state),
            }
            return ActionDecision(
                thought="Relock source-identical interior-line retry to prior invalid-Python statement range.",
                action=CODE_EXECUTE,
                content=self._artifact_virtual_context_noop_command(
                    json.dumps(context, indent=2, sort_keys=True)
                ),
                done=False,
                decision_source="artifact_invalid_python_statement_context_read",
                proposal_metadata={
                    "artifact_invalid_python_statement_context_read": True,
                    "artifact_source_identical_invalid_python_relock": True,
                    "artifact_materialization_retry_attempt": 0,
                    "rejected_command": latest_command,
                    "retry_command": latest_command,
                    "retry_rejected_reason": "invalid_python_replacement",
                    "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                },
            )
        latest_command = ""
        for step in reversed(state.history[-6:]):
            if step.action != CODE_EXECUTE:
                continue
            if self._artifact_materializes(state, str(step.content)):
                latest_command = str(step.content)
                break
        if recent_invalid_python_operations and latest_command:
            statement_preserve_command = self._artifact_invalid_python_preserve_statement_range_retry_command(
                state,
                latest_command,
                invalid_python_details=recent_invalid_python_operations,
                artifact_path=artifact_path,
            )
            if statement_preserve_command:
                return ActionDecision(
                    thought=(
                        "Coerce one-line compound-statement repair into the known full statement range while "
                        "preserving unchanged body lines."
                    ),
                    action=CODE_EXECUTE,
                    content=statement_preserve_command,
                    done=False,
                    decision_source="artifact_invalid_python_statement_range_preserve_direct",
                    proposal_metadata={
                        "artifact_invalid_python_statement_range_preserve_direct": True,
                        "artifact_candidate_path": path or artifact_path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                        "rejected_command": latest_command,
                        "retry_command": statement_preserve_command,
                        "retry_rejected_reason": "invalid_python_statement_range_preserve",
                        "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                    },
                )
            if not any(
                isinstance(step.proposal_metadata, dict)
                and step.proposal_metadata.get("artifact_invalid_python_exhausted_span_context_read")
                for step in state.history[-8:]
            ):
                source_excerpt = ""
                if path:
                    excerpts = self._artifact_fail_to_pass_function_source_excerpts(state, path)
                    if isinstance(excerpts, dict) and excerpts:
                        source_excerpt = "\n\n".join(str(value) for value in excerpts.values())[:2400]
                context = {
                    "mode": "invalid_python_diagnostic_exhausted_span_repair",
                    "artifact_path": artifact_path,
                    "builder_command": builder_command,
                    "path": path,
                    "forbidden_retry_command": latest_command,
                    "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                    "fail_to_pass_function_source_excerpt": source_excerpt,
                    "required_next_action": (
                        "Invalid-Python diagnostics already identified the bad statement span. Do not emit another "
                        "isolated one-line replacement and do not inspect source again. Emit exactly one "
                        "--replace-lines command that preserves the enclosing statement/block syntax, with one "
                        "--with argument per complete replacement source line."
                    ),
                    "valid_command_shape": (
                        f"{builder_command} --path {path or '<path>'} --replace-lines <start> <end> "
                        f"--with '<line1>' [--with '<line2>' ...] > {artifact_path}"
                    ),
                }
                return ActionDecision(
                    thought="Expose a final span-preserving repair packet instead of terminal invalid-Python exhaustion.",
                    action=CODE_EXECUTE,
                    content=self._artifact_virtual_context_noop_command(
                        json.dumps(context, indent=2, sort_keys=True)
                    ),
                    done=False,
                    decision_source="artifact_invalid_python_exhausted_span_context_read",
                    proposal_metadata={
                        "artifact_invalid_python_exhausted_span_context_read": True,
                        "artifact_candidate_path": path or artifact_path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                        "rejected_command": latest_command,
                        "retry_command": latest_command,
                        "retry_rejected_reason": "invalid_python_diagnostic_exhausted",
                        "invalid_python_replacement_operations": recent_invalid_python_operations[:6],
                    },
                )
        return ActionDecision(
            thought="Stop artifact repair before another unbounded model call after invalid Python diagnostics.",
            action="respond",
            content=(
                "Stopping because invalid Python artifact diagnostics did not yield a safe bounded repair for "
                f"{artifact_path}."
            ),
            done=True,
            decision_source="artifact_materialization_guard",
            proposal_metadata={
                "artifact_invalid_python_diagnostic_terminal": True,
                "artifact_candidate_path": artifact_path,
                "artifact_diagnostic_context_count": diagnostic_count,
                "retry_rejected_reason": "invalid_python_diagnostic_exhausted",
            },
        )

    def _artifact_exhausted_diagnostic_escape_decision(self, state: AgentState) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        diagnostic_count = self._artifact_recent_diagnostic_context_count(state)
        exhausted_sources = {
            "artifact_candidate_set_exhausted_context_read",
            "artifact_candidate_cluster_reanchor_context_read",
            "artifact_candidate_cluster_reanchor_failed_context_read",
            "artifact_policy_timeout_single_candidate_context_read",
            "artifact_single_candidate_timeout_minimal_context_read",
            "artifact_single_candidate_range_context_read",
            "artifact_single_candidate_range_failed_context_read",
            "artifact_malformed_json_context_read",
            "artifact_placeholder_comment_only_context_read",
            "artifact_source_inspection_exhausted_context_read",
            "artifact_source_inspection_repeat_blocked_context_read",
        }
        recent_sources = [str(step.decision_source).strip() for step in state.history[-4:]]
        if not any(source in exhausted_sources for source in recent_sources):
            return None
        if (
            state.history
            and str(state.history[-1].decision_source).strip() == "artifact_duplicate_existing_context_read"
        ):
            # The duplicate-context packet is a high-signal negative-memory
            # handoff. Let the normal bounded LLM path consume it once instead
            # of immediately collapsing into exhausted diagnostics.
            return None
        if (
            state.history
            and str(state.history[-1].decision_source).strip()
            == "artifact_source_inspection_repeat_blocked_context_read"
            and any(
                str(step.decision_source).strip() == "artifact_policy_timeout_single_candidate_context_read"
                for step in state.history[-8:]
            )
            and diagnostic_count >= 4
        ):
            contract = artifact_repair_contracts.contract_from_state(state)
            if contract is not None:
                artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
                builder_command = self._artifact_preferred_builder_command(state, contract)
                last_retry_command = ""
                for step in reversed(state.history):
                    if str(step.decision_source).strip() == "artifact_source_inspection_repeat_blocked_context_read":
                        metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
                        last_retry_command = str(metadata.get("retry_command", "")).strip()
                        break
                blocked_context = self._artifact_single_candidate_inspection_blocked_context_read_decision(
                    state,
                    artifact_path=artifact_path,
                    builder_command=builder_command,
                    rejected_command=last_retry_command,
                    retry_attempt=0,
                )
                if blocked_context is not None:
                    return blocked_context
        if (
            state.history
            and str(state.history[-1].decision_source).strip()
            == "artifact_source_inspection_repeat_blocked_context_read"
            and any(
                str(step.decision_source).strip() == "artifact_shallow_patch_context_read"
                for step in state.history[-6:]
            )
            and diagnostic_count >= 5
        ):
            contract = artifact_repair_contracts.contract_from_state(state)
            if contract is not None:
                artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
                builder_command = self._artifact_preferred_builder_command(state, contract)
                artifact_repair_context = self._artifact_retry_context_payload(
                    state,
                    artifact_path=artifact_path,
                    builder_command=builder_command,
                )
                path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
                candidate_records = self._artifact_placeholder_safe_candidate_records(
                    list(artifact_repair_context.get("candidate_edit_records", []) or [])
                )
                if path and candidate_records:
                    command = self._artifact_first_candidate_suggested_replacement_command(
                        state,
                        candidate_records=candidate_records,
                        path=path,
                        artifact_path=artifact_path,
                        builder_command=builder_command,
                    )
                    if command:
                        return ActionDecision(
                            thought=(
                                "Recover from shallow-patch plus repeat-inspection diagnostics with the next "
                                "guarded source-grounded candidate instead of another open-ended model retry."
                            ),
                            action=CODE_EXECUTE,
                            content=command,
                            done=False,
                            decision_source="artifact_shallow_repeat_candidate_suggestion_direct",
                            proposal_metadata={
                                "artifact_shallow_repeat_candidate_suggestion": True,
                                "artifact_candidate_path": path,
                                "artifact_diagnostic_context_count": diagnostic_count,
                            },
                        )
                compact_context = self._artifact_shallow_repeat_timeout_context_read_decision(
                    state,
                    error_text="preempt open-ended retry after shallow patch and repeated source inspection",
                )
                if compact_context is not None:
                    return compact_context
        if state.history and str(state.history[-1].decision_source).strip() in {
            "artifact_malformed_json_context_read",
                "artifact_placeholder_candidate_failed_context_read",
                "artifact_policy_timeout_context_read",
                "artifact_policy_timeout_retry_failed_context_read",
                "artifact_policy_timeout_single_candidate_context_read",
                "artifact_single_candidate_inspection_blocked_context_read",
                "artifact_single_candidate_timeout_minimal_context_read",
                "artifact_single_candidate_range_context_read",
                "artifact_single_candidate_range_failed_context_read",
                "artifact_definition_header_context_read",
            "artifact_definition_header_off_anchor_context_read",
            "artifact_definition_header_repeat_blocked_context_read",
            "artifact_definition_header_body_context_read",
            "artifact_definition_header_body_pre_context_read",
            "artifact_definition_header_body_failed_context_read",
            "artifact_invalid_python_statement_context_read",
            "artifact_invalid_python_declaration_header_context_read",
            "artifact_invalid_python_off_target_context_read",
            "artifact_candidate_cluster_reanchor_context_read",
            "artifact_candidate_cluster_reanchor_failed_context_read",
            "artifact_shallow_patch_context_read",
            "artifact_shallow_patch_repeat_blocked_context_read",
            "artifact_behavior_target_region_escape_context_read",
            "artifact_source_identical_context_read",
            "artifact_noop_after_placeholder_context_read",
            "artifact_placeholder_issue_keyword_escape_context_read",
            "artifact_issue_keyword_range_only_context_read",
            "artifact_range_only_minimal_context_read",
        }:
            # The timeout compaction packet was just added to the trajectory.
            # Likewise, malformed/truncated JSON context carries fresh evidence
            # about why the response failed. Productive repair contexts expose
            # a bounded transformation target. Give the planner one bounded
            # artifact action before treating the diagnostic loop as exhausted.
            return None
        if (
            state.history
            and str(state.history[-1].decision_source).strip()
            == "artifact_source_inspection_repeat_blocked_context_read"
        ):
            latest_metadata = (
                state.history[-1].proposal_metadata
                if isinstance(state.history[-1].proposal_metadata, dict)
                else {}
            )
            has_bounded_repair_packet = bool(
                latest_metadata.get("prior_invalid_python_replacement_operations")
            ) or "fail_to_pass_function_source_excerpts" in str(state.history[-1].content)
            materialized_after_latest_context = any(
                step.index > state.history[-1].index
                and step.action == CODE_EXECUTE
                and self._artifact_materializes(state, str(step.content))
                for step in state.history
            )
            if has_bounded_repair_packet and not materialized_after_latest_context:
                return None
        if (
            state.history
            and str(state.history[-1].decision_source).strip()
            == "artifact_source_inspection_repeat_blocked_context_read"
        ):
            contract = artifact_repair_contracts.contract_from_state(state)
            if contract is not None:
                artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
                builder_command = self._artifact_preferred_builder_command(state, contract)
                artifact_repair_context = self._artifact_retry_context_payload(
                    state,
                    artifact_path=artifact_path,
                    builder_command=builder_command,
                )
                candidate_records = self._artifact_placeholder_safe_candidate_records(
                    list(artifact_repair_context.get("candidate_edit_records", []) or [])
                )
                path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
                if path and candidate_records:
                    command = self._artifact_first_candidate_suggested_replacement_command(
                        state,
                        candidate_records=candidate_records,
                        path=path,
                        artifact_path=artifact_path,
                        builder_command=builder_command,
                    )
                    if command:
                        return ActionDecision(
                            thought=(
                                "Route repeated source-inspection diagnostics into a bounded source-grounded "
                                "candidate instead of another open-ended model retry."
                            ),
                            action=CODE_EXECUTE,
                            content=command,
                            done=False,
                            decision_source="artifact_repeat_source_candidate_suggestion_direct",
                            proposal_metadata={
                                "artifact_repeat_source_candidate_suggestion": True,
                                "artifact_candidate_path": path,
                                "artifact_diagnostic_context_count": diagnostic_count,
                                "retry_rejected_reason": "source_inspection_repeat_blocked",
                            },
                        )
                if diagnostic_count >= 2:
                    return ActionDecision(
                        thought=(
                            "Stop artifact repair after repeated source-inspection diagnostics without a "
                            "guard-valid bounded candidate."
                        ),
                        action="respond",
                        content=(
                            "Stopping because source inspection was repeated after context was already exposed and "
                            f"no guard-valid bounded repair candidate was available for {artifact_path}."
                        ),
                        done=True,
                        decision_source="artifact_materialization_guard",
                        proposal_metadata={
                            "artifact_exhausted_diagnostic_terminal": True,
                            "artifact_source_inspection_repeat_blocked_terminal": True,
                            "artifact_candidate_path": artifact_path,
                            "artifact_diagnostic_context_count": diagnostic_count,
                            "retry_rejected_reason": "source_inspection_repeat_blocked",
                        },
                    )
        if state.history and str(state.history[-1].decision_source).strip() in exhausted_sources:
            # The virtual context was just added to the trajectory. Allow the
            # planner one bounded action using that fresh evidence before
            # converting the diagnostic loop into a terminal stop.
            return None
        if "artifact_source_inspection_repeat_blocked_context_read" in recent_sources:
            min_diagnostic_count = 2
        elif "artifact_source_inspection_exhausted_context_read" in recent_sources:
            min_diagnostic_count = 3
        elif "artifact_policy_timeout_single_candidate_context_read" in recent_sources:
            min_diagnostic_count = 2
        elif "artifact_single_candidate_timeout_minimal_context_read" in recent_sources:
            min_diagnostic_count = 2
        elif "artifact_malformed_json_context_read" in recent_sources:
            min_diagnostic_count = 2
        else:
            min_diagnostic_count = 5
        if diagnostic_count < min_diagnostic_count:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        for step in reversed(state.history):
            if step.action != CODE_EXECUTE:
                continue
            if not self._artifact_materializes(state, str(step.content)):
                continue
            verification = step.verification if isinstance(step.verification, dict) else {}
            reason_text = artifact_repair_contracts.reason_text(verification.get("reasons", []))
            reason_text_lower = reason_text.lower()
            if (
                "isolated one-line production python replacement" not in reason_text_lower
                and "isolated one-line production python assignment replacement" not in reason_text_lower
            ):
                continue
            already_exposed = any(
                later.index > step.index
                and str(later.decision_source).strip() == "artifact_shallow_patch_context_read"
                for later in state.history
            )
            if already_exposed:
                break
            shallow_context = self._artifact_shallow_patch_context_read_decision(
                state,
                command=str(step.content),
                artifact_path=artifact_path,
                retry_attempt=0,
            )
            if shallow_context is not None:
                shallow_context.proposal_metadata = {
                    **dict(shallow_context.proposal_metadata or {}),
                    "artifact_exhausted_diagnostic_shallow_patch_recovery": True,
                }
                return shallow_context
            break
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        candidate_records = self._artifact_placeholder_safe_candidate_records(
            list(artifact_repair_context.get("candidate_edit_records", []) or [])
        )
        recent_retry_reasons = {
            str((step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}).get("retry_rejected_reason", "")).strip()
            for step in state.history[-8:]
        }
        if "artifact_shallow_patch_context_read" in recent_sources and not any(
            str(step.decision_source).strip()
            in {
                "artifact_exhausted_diagnostic_shallow_behavior_context_read",
                "artifact_behavior_target_repair_context_read",
            }
            for step in state.history[-10:]
        ):
            shallow_command = ""
            for step in reversed(state.history):
                if str(step.decision_source).strip() != "artifact_shallow_patch_context_read":
                    continue
                metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
                shallow_command = str(metadata.get("retry_command", "")).strip() or str(step.content).strip()
                if shallow_command:
                    break
            if shallow_command:
                shallow_behavior_context = self._artifact_behavior_target_repair_context_read_decision(
                    state,
                    command=shallow_command,
                    artifact_path=artifact_path,
                    retry_attempt=0,
                )
                if shallow_behavior_context is not None:
                    shallow_behavior_context.thought = (
                        "Recover from exhausted diagnostics after shallow-patch rejection with a structured "
                        "behavior-target repair packet."
                    )
                    shallow_behavior_context.decision_source = (
                        "artifact_exhausted_diagnostic_shallow_behavior_context_read"
                    )
                    shallow_behavior_context.proposal_metadata = {
                        **dict(shallow_behavior_context.proposal_metadata or {}),
                        "artifact_exhausted_diagnostic_shallow_behavior_context_read": True,
                        "artifact_diagnostic_context_count": diagnostic_count,
                        "retry_rejected_reason": "artifact_diagnostic_exhausted",
                    }
                    return shallow_behavior_context
        if path and candidate_records and "definition_header_removal" in recent_retry_reasons:
            command = self._artifact_first_candidate_suggested_replacement_command(
                state,
                candidate_records=candidate_records,
                path=path,
                artifact_path=artifact_path,
                builder_command=builder_command,
            )
            if command:
                return ActionDecision(
                    thought="Recover from exhausted definition-header diagnostics with a guarded body-line candidate.",
                    action=CODE_EXECUTE,
                    content=command,
                    done=False,
                    decision_source="artifact_exhausted_definition_header_candidate_direct",
                    proposal_metadata={
                        "artifact_exhausted_definition_header_candidate": True,
                        "artifact_candidate_path": path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                        "retry_rejected_reason": "definition_header_removal",
                    },
                )
        if (
            path
            and candidate_records
            and not self._artifact_candidate_suggestions_suppressed_by_feedback(state)
        ):
            command = self._artifact_first_candidate_suggested_replacement_command(
                state,
                candidate_records=candidate_records,
                path=path,
                artifact_path=artifact_path,
                builder_command=builder_command,
            )
            if command:
                return ActionDecision(
                    thought="Recover from exhausted artifact diagnostics with a guarded source-grounded candidate.",
                    action=CODE_EXECUTE,
                    content=command,
                    done=False,
                    decision_source="artifact_exhausted_diagnostic_candidate_suggestion_direct",
                    proposal_metadata={
                        "artifact_exhausted_diagnostic_candidate_suggestion": True,
                        "artifact_candidate_path": path,
                        "artifact_diagnostic_context_count": diagnostic_count,
                    },
                )
        if (
            "artifact_single_candidate_timeout_minimal_context_read" in recent_sources
            or "artifact_policy_timeout_single_candidate_context_read" in recent_sources
            or "artifact_malformed_json_context_read" in recent_sources
        ):
            range_context = self._artifact_single_candidate_range_context_read_decision(
                state,
                artifact_path=artifact_path,
                builder_command=builder_command,
                last_retry_command=str(state.history[-1].content if state.history else ""),
                last_retry_rejected_reason="bare_or_incomplete_builder_command",
                effective_rejected_reason="artifact_diagnostic_exhausted",
            )
            if range_context is not None:
                range_context.proposal_metadata = {
                    **dict(range_context.proposal_metadata or {}),
                    "artifact_exhausted_single_candidate_range_recovery": True,
                    "artifact_diagnostic_context_count": diagnostic_count,
                }
                return range_context
        return ActionDecision(
            thought="Stop artifact repair before another unbounded model call after exhausted diagnostics.",
            action="respond",
            content=(
                "Stopping because artifact diagnostics were exhausted without a safe bounded repair for "
                f"{artifact_path}."
            ),
            done=True,
            decision_source="artifact_materialization_guard",
            proposal_metadata={
                "artifact_exhausted_diagnostic_terminal": True,
                "artifact_candidate_path": artifact_path,
                "artifact_diagnostic_context_count": diagnostic_count,
                "retry_rejected_reason": "artifact_diagnostic_exhausted",
            },
        )

    @staticmethod
    def _artifact_controller_failure_terminal_decision(
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        if not LLMDecisionPolicy._artifact_latest_repairable_failure(state):
            return None
        diagnostic_count = LLMDecisionPolicy._artifact_recent_diagnostic_context_count(state)
        if diagnostic_count <= 0:
            return None
        invalid_python_context_count = sum(
            1
            for step in state.history[-6:]
            if str(step.decision_source).strip() == "artifact_invalid_python_statement_context_read"
        )
        if invalid_python_context_count == 1:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        artifact_path = contract.artifact_path if contract is not None else "patch.diff"
        return ActionDecision(
            thought="Stop artifact repair after a controller exception during diagnostic recovery.",
            action="respond",
            content=(
                "Stopping because an internal controller failure occurred after artifact diagnostics without "
                f"materializing {artifact_path}."
            ),
            done=True,
            decision_source="artifact_materialization_guard",
            proposal_metadata={
                "artifact_controller_failure_terminal": True,
                "artifact_candidate_path": artifact_path,
                "artifact_diagnostic_context_count": diagnostic_count,
                "error_preview": str(error_text)[:1200],
                "retry_rejected_reason": "controller_failure",
            },
        )

    @staticmethod
    def _artifact_controller_failure_context_read_decision(
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        if not LLMDecisionPolicy._artifact_latest_repairable_failure(state):
            return None
        if any(
            str(step.decision_source).strip() == "artifact_controller_failure_context_read"
            for step in state.history[-8:]
        ):
            return None
        diagnostic_count = LLMDecisionPolicy._artifact_recent_diagnostic_context_count(state)
        if diagnostic_count <= 0:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        artifact_path = contract.artifact_path if contract is not None else "patch.diff"
        builder_command = artifact_repair_contracts.preferred_builder_command(contract)
        recent_contexts: list[dict[str, object]] = []
        for step in reversed(state.history[-10:]):
            if step.action != CODE_EXECUTE:
                continue
            payload = LLMDecisionPolicy._artifact_context_payload_from_virtual_command(str(step.content))
            if not payload:
                continue
            summary: dict[str, object] = {
                "decision_source": str(step.decision_source).strip(),
                "mode": str(payload.get("mode", "")).strip(),
            }
            for key in (
                "path",
                "requested_source_path",
                "preferred_source_path",
                "allowed_operation_spans",
                "allowed_body_line_numbers",
                "valid_line_numbers_preview",
                "candidate_edit_records",
                "command_skeletons",
                "valid_command_shapes",
                "required_next_action",
            ):
                if key in payload:
                    value = payload.get(key)
                    if isinstance(value, list):
                        summary[key] = value[:8]
                    else:
                        summary[key] = value
            recent_contexts.append(summary)
            if len(recent_contexts) >= 4:
                break
        if not recent_contexts:
            return None
        context = {
            "mode": "controller_failure_after_artifact_diagnostics",
            "artifact_path": artifact_path,
            "builder_command": builder_command,
            "error_preview": str(error_text)[:500],
            "recent_diagnostic_contexts": list(reversed(recent_contexts)),
            "action_failure_memory": LLMDecisionPolicy._artifact_action_failure_memory(state),
            "required_next_action": (
                "A controller exception occurred after diagnostic context was already exposed. Do not stop, "
                "do not inspect source again, and do not repeat blocked commands. Use the most recent allowed "
                "operation spans, candidate_edit_records, or command_skeletons to emit one concrete builder "
                f"command that writes {artifact_path}."
            ),
            "valid_command_shapes": [
                f"{builder_command} --path <path> --replace-line <line> --with '<replacement source line>' > {artifact_path}",
                f"{builder_command} --path <path> --replace-lines <start> <end> --with '<line1>' [--with '<line2>' ...] > {artifact_path}",
            ],
        }
        return ActionDecision(
            thought="Recover from controller failure by re-exposing bounded artifact repair context.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_controller_failure_context_read",
            proposal_metadata={
                "artifact_controller_failure_context_read": True,
                "artifact_candidate_path": artifact_path,
                "artifact_diagnostic_context_count": diagnostic_count,
                "retry_rejected_reason": "controller_failure",
                "error_preview": str(error_text)[:1200],
            },
        )

    @staticmethod
    def _artifact_recent_diagnostic_context_count(state: AgentState, *, window: int = 6) -> int:
        diagnostic_sources = {
            "artifact_source_lines_followup_direct",
            "artifact_expected_behavior_source_lines_followup_direct",
            "artifact_inference_failure_source_context_fallback",
            "artifact_placeholder_candidate_guard_context_read",
            "artifact_invalid_python_statement_context_read",
            "artifact_invalid_python_declaration_header_context_read",
            "artifact_invalid_python_off_target_context_read",
            "artifact_candidate_set_exhausted_context_read",
            "artifact_candidate_cluster_reanchor_context_read",
            "artifact_candidate_cluster_reanchor_failed_context_read",
            "artifact_broad_replacement_context_read",
            "artifact_source_inspection_exhausted_context_read",
            "artifact_shallow_patch_context_read",
            "artifact_definition_header_context_read",
            "artifact_definition_header_off_anchor_context_read",
            "artifact_definition_header_repeat_blocked_context_read",
            "artifact_definition_header_body_context_read",
            "artifact_definition_header_body_pre_context_read",
            "artifact_definition_header_body_failed_context_read",
            "artifact_malformed_json_context_read",
            "artifact_policy_timeout_context_read",
            "artifact_policy_timeout_single_candidate_context_read",
            "artifact_source_inspection_repeat_blocked_context_read",
            "artifact_single_candidate_inspection_blocked_context_read",
            "artifact_single_candidate_timeout_minimal_context_read",
            "artifact_source_identical_context_read",
        }
        return sum(
            1
            for step in state.history[-max(1, int(window)) :]
            if str(step.decision_source).strip() in diagnostic_sources
            or artifact_repair_contracts.command_is_source_inspection(str(step.content).strip())
        )

    @staticmethod
    def _artifact_backoff_failure_count(state: AgentState) -> int:
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        failures = metadata.get("artifact_backoff_failures", [])
        if isinstance(failures, list):
            return sum(1 for item in failures if isinstance(item, dict))
        return int(isinstance(metadata.get("artifact_last_backoff_failure"), dict))

    @staticmethod
    def _artifact_source_identical_context_read_decision(
        state: AgentState,
        *,
        command: str,
        artifact_path: str,
        retry_attempt: int,
    ) -> ActionDecision | None:
        details = LLMDecisionPolicy._artifact_source_identical_operation_details(state, command)
        if not details:
            return None
        command_hash = hashlib.sha256(str(command).encode("utf-8", errors="ignore")).hexdigest()[:16]
        paths = {str(detail.get("path", "")).strip() for detail in details if str(detail.get("path", "")).strip()}
        spans = {
            f"{str(detail.get('path', '')).strip()}:{int(detail.get('start_line', 0) or 0)}:{int(detail.get('end_line', 0) or 0)}"
            for detail in details
            if str(detail.get("path", "")).strip()
        }
        for step in state.history:
            if str(step.decision_source).strip() != "artifact_source_identical_context_read":
                continue
            return None
            metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
            if str(metadata.get("retry_command_hash", "")).strip() == command_hash:
                return None
            previous_spans = {
                str(value).strip()
                for value in metadata.get("operation_spans", [])
                if str(value).strip()
            } if isinstance(metadata.get("operation_spans", []), list) else set()
            if spans and previous_spans.intersection(spans):
                return None
        context = {
            "mode": "source_identical_noop_rejected",
            "artifact_path": artifact_path,
            "rejected_command": str(command)[:1500],
            "source_identical_noop_operations": details[:8],
            "required_next_action": (
                "The rejected command copies existing source without changing behavior. Do not repeat the same "
                "line/span/replacement; use the suggested statement range or adjacent executable lines to make a "
                "real behavior-changing edit."
            ),
        }
        return ActionDecision(
            thought="Expose source-identical no-op context and require a behavior-changing repair.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_source_identical_context_read",
            proposal_metadata={
                "artifact_source_identical_context_read": True,
                "artifact_materialization_retry_attempt": retry_attempt,
                "retry_command": command,
                "retry_command_hash": command_hash,
                "retry_rejected_reason": "source_identical_noop",
                "artifact_candidate_path": sorted(paths)[0] if paths else "",
                "operation_spans": sorted(spans),
            },
        )

    @staticmethod
    def _artifact_python_line_shape_compatible(original_line: str, replacement_line: str) -> bool:
        original = str(original_line).strip()
        replacement = str(replacement_line).strip()
        if not original or not replacement:
            return False
        string_prefixes = ('"""', "'''", '"', "'")
        if replacement.startswith(string_prefixes):
            return False
        if original.startswith(string_prefixes):
            return False

        def keyword_shape(value: str) -> str:
            for prefix, shape in (
                ("async def ", "async def"),
                ("def ", "def"),
                ("class ", "class"),
                ("if ", "if"),
                ("elif ", "elif"),
                ("else:", "else"),
                ("for ", "for"),
                ("while ", "while"),
                ("try:", "try"),
                ("except ", "except"),
                ("finally:", "finally"),
                ("with ", "with"),
                ("return ", "return"),
                ("raise ", "raise"),
                ("yield ", "yield"),
                ("assert ", "assert"),
                ("import ", "import"),
                ("from ", "from"),
            ):
                if value.startswith(prefix):
                    return shape
            return ""

        original_shape = keyword_shape(original)
        replacement_shape = keyword_shape(replacement)
        if original_shape or replacement_shape:
            return original_shape == replacement_shape
        if ("=" in original) != ("=" in replacement):
            return False
        if original.endswith(",") and replacement.endswith(","):
            original_call = re.search(r"=\s*([A-Za-z_][A-Za-z0-9_\.]*)\s*\(", original)
            replacement_call = re.search(r"=\s*([A-Za-z_][A-Za-z0-9_\.]*)\s*\(", replacement)
            if (
                original_call
                and replacement_call
                and original_call.group(1) != replacement_call.group(1)
            ):
                return False
        return True

    @staticmethod
    def _artifact_python_header_signature_range(
        state: AgentState,
        path: str,
        *,
        start_line: int,
    ) -> dict[str, object]:
        normalized_path = str(path).strip().strip("/")
        if not normalized_path.endswith(".py"):
            return {}
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, normalized_path)
        if not source_text or LLMDecisionPolicy._artifact_python_compile_error(source_text, normalized_path):
            return {}
        source_lines = source_text.splitlines()
        if start_line < 1 or start_line > len(source_lines):
            return {}
        first_line = source_lines[start_line - 1]
        first_stripped = first_line.strip()
        if not first_stripped.startswith(("def ", "async def ", "class ")):
            return {}
        bracket_depth = 0
        for index in range(start_line - 1, min(len(source_lines), start_line + 500)):
            line = source_lines[index]
            for char in line:
                if char in "([{":
                    bracket_depth += 1
                elif char in ")]}":
                    bracket_depth = max(0, bracket_depth - 1)
            if line.strip().endswith(":") and bracket_depth == 0:
                return {
                    "start_line": int(start_line),
                    "end_line": index + 1,
                    "source": "\n".join(source_lines[start_line - 1 : index + 1]),
                }
        return {}

    @staticmethod
    def _artifact_expand_partial_header_signature_builder_command(
        state: AgentState,
        command: str,
        *,
        artifact_path: str,
    ) -> str:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return ""
        operations = list(spec.get("operations", []))
        if len(operations) != 1:
            return ""
        start_line, end_line, replacement_lines = operations[0]
        builder = str(spec.get("builder") or "patch_builder").strip() or "patch_builder"
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return ""
        replacement_values = LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines)
        if len(replacement_values) != 1:
            return ""
        replacement = str(replacement_values[0]).rstrip("\n")
        if not replacement.strip().startswith(("def ", "async def ", "class ")):
            return ""
        if not replacement.strip().endswith(":"):
            return ""
        signature_range = LLMDecisionPolicy._artifact_python_header_signature_range(
            state,
            path,
            start_line=int(start_line),
        )
        signature_end = int(signature_range.get("end_line", 0) or 0)
        if signature_end <= int(end_line):
            return ""
        candidate = (
            f"{builder} --path {shlex.quote(path)} --replace-lines {int(start_line)} {signature_end} "
            f"--with {shlex.quote(replacement)} > {artifact_path}"
        )
        if LLMDecisionPolicy._artifact_builder_guard_rejection_reason(state, candidate):
            return ""
        return candidate

    @staticmethod
    def _artifact_split_escaped_newline_builder_command(
        state: AgentState,
        command: str,
        *,
        artifact_path: str,
    ) -> str:
        candidate, rejection_reason = LLMDecisionPolicy._artifact_split_escaped_newline_builder_candidate(
            state,
            command,
            artifact_path=artifact_path,
        )
        if rejection_reason:
            return ""
        return candidate

    @staticmethod
    def _artifact_split_escaped_newline_builder_rejection_reason(
        state: AgentState,
        command: str,
        *,
        artifact_path: str,
    ) -> str:
        candidate, rejection_reason = LLMDecisionPolicy._artifact_split_escaped_newline_builder_candidate(
            state,
            command,
            artifact_path=artifact_path,
        )
        del candidate
        return rejection_reason

    @staticmethod
    def _artifact_expand_multiline_single_line_builder_command(
        state: AgentState,
        command: str,
        *,
        artifact_path: str,
    ) -> str:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=True)
        if spec is None:
            return ""
        operations = list(spec.get("operations", []) or [])
        if len(operations) != 1:
            return ""
        start_line, end_line, replacement_lines = operations[0]
        try:
            start = int(start_line)
            end = int(end_line)
        except (TypeError, ValueError):
            return ""
        expanded = LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines)
        if start != end or len(expanded) <= 1:
            return ""
        if any("\n" in str(line) or "\\n" in str(line) for line in expanded):
            return ""
        builder = str(spec.get("builder") or "patch_builder").strip() or "patch_builder"
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return ""
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        source_line = source_by_number.get(start, "")
        source_indent = source_line[: len(source_line) - len(source_line.lstrip())]

        def normalize_line(raw: object) -> str:
            line = re.sub(r"^\s*\d+:\s?", "", str(raw).rstrip("\n"))
            if source_indent and line.strip():
                line_indent = line[: len(line) - len(line.lstrip())]
                if not line_indent or len(line_indent) < len(source_indent):
                    return f"{source_indent}{line.lstrip()}"
            return line

        normalized_lines = [normalize_line(line) for line in expanded]
        candidate_end = start + len(normalized_lines) - 1
        candidate = (
            f"{builder} --path {shlex.quote(path)} --replace-lines {start} {candidate_end} "
            + " ".join(f"--with {shlex.quote(line)}" for line in normalized_lines)
            + f" > {artifact_path}"
        )
        if LLMDecisionPolicy._artifact_builder_guard_rejection_reason(state, candidate):
            return ""
        return candidate

    @staticmethod
    def _artifact_escaped_newline_split_rejected_context_read_decision(
        state: AgentState,
        *,
        command: str,
        artifact_path: str,
        builder_command: str,
        retry_attempt: int,
    ) -> ActionDecision | None:
        split_candidate, split_rejection_reason = (
            LLMDecisionPolicy._artifact_split_escaped_newline_builder_candidate(
                state,
                command,
                artifact_path=artifact_path,
            )
        )
        split_candidate_available = bool(split_candidate)
        if not split_candidate:
            spec = LLMDecisionPolicy._artifact_builder_command_spec(
                state,
                command,
                require_redirect=False,
            )
            if spec is None:
                return None
            operations = list(spec.get("operations", []) or [])
            if not operations:
                return None
            split_rejection_reason = "split_candidate_unavailable"
        prior_same_split_rejection = any(
            str(step.decision_source).strip() == "artifact_escaped_newline_split_rejected_context_read"
            and str(
                (step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}).get(
                    "retry_rejected_reason",
                    "",
                )
            ).strip()
            == str(split_rejection_reason or "").strip()
            for step in state.history
        )
        if prior_same_split_rejection and str(split_rejection_reason).strip() == "statement_kind_replacement":
            statement_kind_decision = (
                LLMDecisionPolicy._artifact_escaped_newline_statement_kind_context_read_decision(
                    state,
                    command=command,
                    split_candidate=split_candidate,
                    artifact_path=artifact_path,
                    builder_command=builder_command,
                    retry_attempt=retry_attempt,
                )
            )
            if statement_kind_decision is not None:
                return statement_kind_decision
        context = {
            "mode": "escaped_newline_split_rejected",
            "artifact_path": artifact_path,
            "rejected_command": str(command),
            "split_candidate": split_candidate,
            "split_candidate_available": split_candidate_available,
            "split_rejection_reason": split_rejection_reason or "unknown",
            "fail_to_pass_test_source_excerpts": LLMDecisionPolicy._artifact_fail_to_pass_test_source_excerpts(state),
            "required_next_action": (
                "The model put multiple source lines inside one --with payload. The kernel split that into a "
                "proper --replace-lines command, but the split candidate still violated the artifact guard. Emit "
                "one new builder command that keeps one --with per output line and fixes the split_rejection_reason; "
                "do not inspect source and do not put literal newlines inside a single --with."
            ),
            "valid_command_shape": (
                f"{builder_command} --path <path> --replace-lines <start> <end> "
                f"--with '<line1>' [--with '<line2>' ...] > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Expose escaped-newline split rejection as bounded repair context instead of terminalizing.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_escaped_newline_split_rejected_context_read",
            proposal_metadata={
                "artifact_escaped_newline_split_rejected_context_read": True,
                "artifact_materialization_retry_attempt": retry_attempt,
                "rejected_command": command,
                "retry_command": split_candidate,
                "retry_rejected_reason": split_rejection_reason or "escaped_newline_replacement",
            },
        )

    @staticmethod
    def _artifact_escaped_newline_statement_kind_context_read_decision(
        state: AgentState,
        *,
        command: str,
        split_candidate: str,
        artifact_path: str,
        builder_command: str,
        retry_attempt: int,
    ) -> ActionDecision | None:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return None
        operations = list(spec.get("operations", []) or [])
        if len(operations) != 1:
            return None
        start_line, end_line, replacement_lines = operations[0]
        try:
            start = int(start_line)
            end = int(end_line)
        except (TypeError, ValueError):
            return None
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return None
        expanded_replacements = LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines)
        if expanded_replacements:
            end = max(end, start + len(expanded_replacements) - 1)
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        fail_to_pass_body_lines = LLMDecisionPolicy._artifact_fail_to_pass_body_line_numbers(state, path)
        if fail_to_pass_body_lines:
            body_set = set(fail_to_pass_body_lines)
            if not any(start <= line_number <= end for line_number in body_set):
                start = min(fail_to_pass_body_lines)
                end = max(fail_to_pass_body_lines[: min(len(fail_to_pass_body_lines), 12)])
        source_lines: list[str] = []
        required_prefixes: set[str] = set()
        for line_number in range(start, end + 1):
            line = str(source_by_number.get(line_number, ""))
            if not line:
                continue
            source_lines.append(f"{line_number}: {line}")
            stripped = line.lstrip()
            indent = line[: len(line) - len(stripped)]
            if stripped.startswith("return "):
                required_prefixes.add(f"{indent}return ")
            elif stripped.startswith("raise "):
                required_prefixes.add(f"{indent}raise ")
            elif stripped.startswith("yield "):
                required_prefixes.add(f"{indent}yield ")
        if not source_lines:
            return None
        context = {
            "mode": "escaped_newline_statement_kind_repair",
            "artifact_path": artifact_path,
            "path": path,
            "rejected_command": str(command)[:1500],
            "split_candidate": str(split_candidate)[:1500],
            "rejected_reason": "statement_kind_replacement",
            "allowed_operation_spans": [f"{start}:{end}"],
            "target_source_lines": "\n".join(source_lines)[:1200],
            "required_replacement_prefixes": sorted(required_prefixes),
            "required_next_action": (
                "The escaped-newline split repair was already rejected for changing the target statement kind. "
                "Do not repeat the split repair. Emit one span-bound builder command that preserves the target "
                "statement kind and indentation. If required_replacement_prefixes is non-empty, every replacement "
                "line must start with one of those prefixes."
            ),
            "valid_command_shape": (
                f"{builder_command} --path {path} --replace-lines {start} {end} "
                f"--with '<same-kind statement line>' [--with '<same-kind continuation>' ...] > {artifact_path}"
            ),
        }
        return ActionDecision(
            thought="Escalate repeated escaped-newline statement-kind rejection to span-bound statement repair.",
            action=CODE_EXECUTE,
            content=LLMDecisionPolicy._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_escaped_newline_statement_kind_context_read",
            proposal_metadata={
                "artifact_escaped_newline_statement_kind_context_read": True,
                "artifact_materialization_retry_attempt": retry_attempt,
                "rejected_command": command,
                "retry_command": split_candidate,
                "retry_rejected_reason": "escaped_newline_statement_kind_repair",
                "artifact_candidate_path": path,
                "operation_spans": [f"{start}:{end}"],
            },
        )

    @staticmethod
    def _artifact_split_escaped_newline_builder_candidate(
        state: AgentState,
        command: str,
        *,
        artifact_path: str,
    ) -> tuple[str, str]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=True)
        if spec is None:
            return "", ""
        operations = list(spec.get("operations", []))
        if len(operations) != 1:
            return "", ""
        start_line, _end_line, replacement_lines = operations[0]
        split_replacements: list[str] = []
        saw_newline = False
        path = str(spec.get("path") or "").strip().strip("/")
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        source_line = source_by_number.get(int(start_line), "")
        source_indent = source_line[: len(source_line) - len(source_line.lstrip())]

        def normalize_split_line(value: str) -> str:
            line = re.sub(r"^\s*\d+:\s?", "", str(value).rstrip("\n"))
            if source_indent and line.strip():
                line_indent = line[: len(line) - len(line.lstrip())]
                if not line_indent:
                    return f"{source_indent}{line}"
                if len(line_indent) < len(source_indent):
                    return f"{source_indent}{line}"
            return line

        for raw_line in replacement_lines:
            line = str(raw_line).rstrip("\n")
            if "\\n" in line:
                saw_newline = True
                split_replacements.extend(normalize_split_line(item) for item in line.split("\\n"))
            elif "\n" in line:
                saw_newline = True
                split_replacements.extend(normalize_split_line(item) for item in line.splitlines())
            else:
                split_replacements.append(normalize_split_line(line))
        if not saw_newline and len(replacement_lines) > 1 and int(_end_line) == int(start_line):
            # The shell parser can already split a quoted multiline --with
            # value into several replacement values. Treat that as the same
            # repair case as an escaped newline inside one --with argument.
            saw_newline = True
        if not saw_newline or not split_replacements:
            return "", ""
        builder = str(spec.get("builder") or "patch_builder").strip() or "patch_builder"
        if not path:
            return "", ""
        start = int(start_line)
        end = start + len(split_replacements) - 1
        candidate = (
            f"{builder} --path {shlex.quote(path)} --replace-lines {start} {end} "
            + " ".join(f"--with {shlex.quote(line)}" for line in split_replacements)
            + f" > {artifact_path}"
        )
        rejection_reason = LLMDecisionPolicy._artifact_builder_guard_rejection_reason(state, candidate)
        if rejection_reason:
            return candidate, rejection_reason
        return candidate, ""

    @staticmethod
    def _artifact_broad_builder_last_resort_allowed(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=True)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        if LLMDecisionPolicy._artifact_builder_uses_artifact_as_source(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_uses_unknown_source_path(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_line_out_of_known_source_range(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_has_placeholder_replacement(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_has_comment_only_replacement(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_replaces_existing_source(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_removes_definition_header(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_has_escaped_newline_replacement(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_would_produce_invalid_python(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_python_ast_unchanged(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_unused_python_parameter_names(state, command):
            return False
        if LLMDecisionPolicy._artifact_builder_invalid_init_return_names(state, command):
            return False
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            source_span = int(end_line) - int(start_line) + 1
            replacement_span = len(LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines))
            if source_span > 80 or replacement_span > 80:
                return False
        return True

    @staticmethod
    def _artifact_builder_removes_definition_header(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        if not source_text:
            return False
        source_lines = source_text.splitlines()
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                continue
            original_headers = [
                line.strip()
                for line in source_lines[start_line - 1 : end_line]
                if line.strip().startswith(("def ", "async def ", "class "))
            ]
            replacement_header_set = {
                str(line).strip()
                for line in LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines)
                if str(line).strip().startswith(("def ", "async def ", "class "))
            }
            replacement_line_count = len(LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines))
            source_span = int(end_line) - int(start_line) + 1
            if replacement_header_set and not original_headers:
                return True
            if replacement_header_set and original_headers and source_span == 1 and replacement_line_count > 1:
                return True
            original_header_kinds = {
                "async def"
                if header.startswith("async def ")
                else "def"
                if header.startswith("def ")
                else "class"
                for header in original_headers
            }
            replacement_header_kinds = {
                "async def"
                if header.startswith("async def ")
                else "def"
                if header.startswith("def ")
                else "class"
                for header in replacement_header_set
            }
            if original_headers and not original_header_kinds.issubset(replacement_header_kinds):
                return True
            original_header_names = {
                name
                for header in original_headers
                for name in [LLMDecisionPolicy._artifact_definition_header_name(header)]
                if name
            }
            replacement_header_names = {
                name
                for header in replacement_header_set
                for name in [LLMDecisionPolicy._artifact_definition_header_name(header)]
                if name
            }
            if original_header_names and not original_header_names.issubset(replacement_header_names):
                return True
        return False

    @staticmethod
    def _artifact_definition_header_name(header: str) -> str:
        match = re.match(r"\s*(?:async\s+def|def|class)\s+([A-Za-z_][A-Za-z0-9_]*)\b", str(header))
        return match.group(1) if match else ""

    @staticmethod
    def _artifact_builder_command_prefix(state: AgentState, command: str) -> bool:
        normalized = str(command).strip()
        if not normalized:
            return False
        contract = artifact_repair_contracts.contract_from_state(state)
        builder_commands = (
            contract.builder_commands if contract is not None else artifact_repair_contracts.PATCH_BUILDER_COMMANDS
        )
        return any(normalized.startswith(f"{builder} ") for builder in builder_commands)

    @staticmethod
    def _artifact_builder_uses_artifact_as_source(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        contract = artifact_repair_contracts.contract_from_state(state)
        artifact_path = contract.artifact_path if contract is not None else "patch.diff"
        return str(spec.get("path") or "").strip().strip("/") == str(artifact_path).strip().strip("/")

    @staticmethod
    def _artifact_builder_uses_unknown_source_path(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        known_paths = {str(candidate).strip().strip("/") for candidate in LLMDecisionPolicy._artifact_source_context_by_path(state)}
        if not known_paths:
            return False
        return path not in known_paths

    @staticmethod
    def _artifact_builder_line_out_of_known_source_range(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        source_text = (
            LLMDecisionPolicy._artifact_swe_base_source_text(state, path)
            or LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        )
        if source_text:
            line_count = len(source_text.splitlines())
            for start_line, end_line, _replacement_lines in spec.get("operations", []):
                if start_line < 1 or end_line < start_line or end_line > line_count:
                    return True
            return False
        known_line_numbers = LLMDecisionPolicy._artifact_source_line_numbers_for_path(state, path)
        if known_line_numbers:
            minimum = min(known_line_numbers)
            maximum = max(known_line_numbers)
            for start_line, end_line, _replacement_lines in spec.get("operations", []):
                if start_line < minimum or end_line < start_line or end_line > maximum:
                    return True
            return False
        return False

    @staticmethod
    def _artifact_builder_escapes_behavior_target_region(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        behavior_metadata: dict[str, object] = {}
        for step in reversed(state.history):
            if str(step.decision_source).strip() != "artifact_behavior_target_repair_context_read":
                continue
            metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
            if str(metadata.get("artifact_candidate_path", "")).strip().strip("/") == path:
                behavior_metadata = dict(metadata)
                break
        if not behavior_metadata:
            return False
        raw_spans = behavior_metadata.get("operation_spans", [])
        if not isinstance(raw_spans, list):
            return False
        spans: list[tuple[int, int]] = []
        for item in raw_spans:
            try:
                start_text, end_text = str(item).split(":", 1)
                start = int(start_text)
                end = int(end_text)
            except (TypeError, ValueError):
                continue
            spans.append((max(1, start - 8), end + 8))
        if not spans:
            return False
        for start_line, end_line, _replacement_lines in spec.get("operations", []):
            start = int(start_line)
            end = int(end_line)
            if not any(start <= allowed_end and end >= allowed_start for allowed_start, allowed_end in spans):
                return True
        return False

    @staticmethod
    def _artifact_builder_has_placeholder_replacement(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        placeholder_literals = {
            "...",
            "changed",
            "new_code",
            "new_code_here",
            "replacement",
            "replacement_code",
            "todo",
            "your_code_here",
        }
        for _start_line, _end_line, replacement_lines in spec.get("operations", []):
            stripped_lines = [str(line).strip() for line in replacement_lines if str(line).strip()]
            if not stripped_lines:
                continue
            lowered = [line.lower().strip("'\"") for line in stripped_lines]
            if all(line in placeholder_literals for line in lowered):
                return True
            if all(
                re.match(
                    r"print\((['\"])(test|hello|patch applied|success|done|fixed|works)\1\)",
                    line,
                    re.IGNORECASE,
                )
                for line in stripped_lines
            ):
                return True
            if all(line in {"assert True", "assert False"} for line in stripped_lines):
                return True
        return False

    @staticmethod
    def _artifact_builder_has_comment_only_replacement(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        for _start_line, _end_line, replacement_lines in spec.get("operations", []):
            stripped_lines = [str(line).strip() for line in replacement_lines if str(line).strip()]
            if stripped_lines and all(line.startswith("#") for line in stripped_lines):
                return True
            if stripped_lines and all(
                line.startswith(('"""', "'''")) or line.endswith(('"""', "'''"))
                for line in stripped_lines
            ):
                return True
        return False

    @staticmethod
    def _artifact_builder_guard_rejection_details(
        state: AgentState,
        reason: str,
        command: str,
    ) -> list[dict[str, object]]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        known_line_numbers = LLMDecisionPolicy._artifact_source_line_numbers_for_path(state, path) if path else []
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path) if path else ""
        line_count = len(source_text.splitlines()) if source_text else 0
        details: list[dict[str, object]] = []
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            replacement_preview = "\n".join(str(line).rstrip("\n") for line in replacement_lines)
            detail: dict[str, object] = {
                "reason": str(reason),
                "path": path,
                "start_line": int(start_line),
                "end_line": int(end_line),
                "replacement_preview": replacement_preview[:800],
            }
            if line_count:
                detail["known_source_line_count"] = line_count
            if known_line_numbers:
                detail["known_source_line_min"] = min(known_line_numbers)
                detail["known_source_line_max"] = max(known_line_numbers)
            if reason == "python_ast_noop":
                detail["semantic_issue"] = "python AST unchanged after ignoring docstrings/comments"
            elif reason == "string_literal_only_change":
                detail["semantic_issue"] = "patch changes only Python string literal values"
            elif reason == "annotation_only_change":
                detail["semantic_issue"] = "patch changes only Python type annotations"
            elif reason == "indentation_only_statement_move":
                moves = LLMDecisionPolicy._artifact_builder_indentation_only_statement_moves(state, command)
                if moves:
                    detail["indentation_only_statement_moves"] = moves[:8]
            elif reason == "unused_signature_parameter":
                unused_params = LLMDecisionPolicy._artifact_builder_unused_python_parameter_names(state, command)
                if unused_params:
                    detail["unused_parameters"] = unused_params[:8]
            elif reason == "invalid_init_return_value":
                invalid_inits = LLMDecisionPolicy._artifact_builder_invalid_init_return_names(state, command)
                if invalid_inits:
                    detail["invalid_init_returns"] = invalid_inits[:8]
            elif reason == "invalid_init_generator":
                invalid_generators = LLMDecisionPolicy._artifact_builder_invalid_init_generator_names(state, command)
                if invalid_generators:
                    detail["invalid_init_generators"] = invalid_generators[:8]
            elif reason == "local_use_before_assignment":
                unbound_locals = LLMDecisionPolicy._artifact_builder_local_load_before_assignment_names(state, command)
                if unbound_locals:
                    detail["local_use_before_assignment"] = unbound_locals[:8]
            elif reason == "disallowed_swe_solution_path":
                detail["semantic_issue"] = "SWE patch attempted to edit tests or auxiliary update artifacts"
            elif reason == "placeholder_output_replacement":
                detail["semantic_issue"] = "replacement substitutes real behavior or error handling with placeholder output"
            elif reason == "config_key_replacement":
                replacements = LLMDecisionPolicy._artifact_builder_suspicious_config_key_replacement_details(
                    state, command
                )
                if replacements:
                    detail["config_key_replacements"] = replacements[:8]
            elif reason == "non_python_language_mismatch":
                detail["semantic_issue"] = "replacement inserts Python-looking code into a non-Python file"
            elif reason == "semantic_token_flip":
                token_flips = LLMDecisionPolicy._artifact_builder_suspicious_semantic_token_flip_details(state, command)
                if token_flips:
                    detail["semantic_token_flips"] = token_flips[:8]
            elif reason == "module_registration_removed":
                removed_registrations = LLMDecisionPolicy._artifact_builder_removed_module_registration_names(
                    state, command
                )
                if removed_registrations:
                    detail["removed_module_registrations"] = removed_registrations[:8]
            elif reason == "unknown_attribute_replacement":
                attr_replacements = LLMDecisionPolicy._artifact_builder_suspicious_attribute_replacement_details(
                    state, command
                )
                if attr_replacements:
                    detail["unknown_attribute_replacements"] = attr_replacements[:8]
            elif reason == "private_attribute_read":
                private_attrs = LLMDecisionPolicy._artifact_builder_introduced_private_attribute_accesses(state, command)
                if not private_attrs:
                    private_attrs = [
                        f"self.{item}"
                        for item in LLMDecisionPolicy._artifact_builder_introduced_unknown_self_private_attribute_accesses(
                            state, command
                        )
                    ]
                if private_attrs:
                    detail["private_attribute_reads"] = private_attrs[:8]
            elif reason == "exception_contract_regression":
                exception_regressions = LLMDecisionPolicy._artifact_builder_exception_contract_regression_details(
                    state, command
                )
                if exception_regressions:
                    detail["exception_contract_regressions"] = exception_regressions[:8]
            elif reason == "redundant_decorated_normalization":
                redundant_normalizations = (
                    LLMDecisionPolicy._artifact_builder_redundant_decorated_normalization_details(state, command)
                )
                if redundant_normalizations:
                    detail["redundant_decorated_normalizations"] = redundant_normalizations[:8]
            elif reason == "duplicate_call_wrapper":
                duplicate_wrappers = LLMDecisionPolicy._artifact_builder_duplicate_surrounding_call_wrapper_details(
                    state, command
                )
                if duplicate_wrappers:
                    detail["duplicate_call_wrappers"] = duplicate_wrappers[:8]
            elif reason == "self_recursive_property_access":
                recursive_properties = LLMDecisionPolicy._artifact_builder_introduced_self_recursive_property_accesses(
                    state, command
                )
                if recursive_properties:
                    detail["self_recursive_property_accesses"] = recursive_properties[:8]
            elif reason == "self_recursive_method_call":
                recursive_calls = LLMDecisionPolicy._artifact_builder_introduced_self_recursive_method_calls(
                    state, command
                )
                if recursive_calls:
                    detail["self_recursive_method_calls"] = recursive_calls[:8]
            elif reason == "nested_assignment_replacement":
                nested_assignments = LLMDecisionPolicy._artifact_builder_nested_assignment_replacement_details(
                    state, command
                )
                if nested_assignments:
                    detail["nested_assignment_replacements"] = nested_assignments[:8]
            elif reason == "unresolved_name_read":
                unresolved_names = LLMDecisionPolicy._artifact_builder_introduced_unresolved_name_loads(state, command)
                if unresolved_names:
                    detail["unresolved_name_reads"] = unresolved_names[:8]
            elif reason == "return_value_path_removed":
                removed_returns = LLMDecisionPolicy._artifact_builder_removed_return_value_paths(state, command)
                if removed_returns:
                    detail["removed_return_value_paths"] = removed_returns[:8]
            elif reason == "none_return_value_introduced":
                none_returns = LLMDecisionPolicy._artifact_builder_introduced_none_return_value_paths(state, command)
                if none_returns:
                    detail["introduced_none_return_value_paths"] = none_returns[:8]
            elif reason == "suspicious_boolean_return_flip":
                risky_flips = LLMDecisionPolicy._artifact_builder_suspicious_boolean_return_flip_names(state, command)
                if risky_flips:
                    detail["suspicious_boolean_return_flips"] = risky_flips[:8]
            elif reason == "statement_kind_replacement":
                regressions = LLMDecisionPolicy._artifact_builder_suspicious_statement_replacement_details(
                    state, command
                )
                if not regressions:
                    regressions = [
                        f"nested duplicate reducer {item}"
                        for item in LLMDecisionPolicy._artifact_builder_nested_duplicate_reducer_details(state, command)
                    ]
                if regressions:
                    detail["statement_kind_replacements"] = regressions[:8]
            elif reason == "shallow_one_line_patch":
                detail["semantic_issue"] = (
                    "isolated one-line production replacement is too weak for SWE patch completion; "
                    "use a structured multi-line repair"
                )
            details.append(detail)
        if not details and path:
            details.append({"reason": str(reason), "path": path, "known_source_line_count": line_count})
        return details

    @staticmethod
    def _artifact_builder_has_escaped_newline_replacement(state: AgentState, command: str) -> bool:
        normalized = str(command)
        if "\n" in normalized and "--with" in normalized and LLMDecisionPolicy._artifact_builder_command_prefix(
            state,
            normalized.strip(),
        ):
            return True
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        for _start_line, _end_line, replacement_lines in spec.get("operations", []):
            if any("\\n" in str(line) or "\n" in str(line).rstrip("\n") for line in replacement_lines):
                return True
        return False

    @staticmethod
    def _artifact_non_materializing_repair_command(state: AgentState, command: str) -> bool:
        normalized = str(command).strip()
        if not normalized:
            return False
        if LLMDecisionPolicy._artifact_builder_command_prefix(state, normalized):
            return True
        return artifact_repair_contracts.command_is_source_inspection(normalized)

    @staticmethod
    def _artifact_source_context_available(state: AgentState) -> bool:
        return bool(LLMDecisionPolicy._artifact_source_context_by_path(state))

    @staticmethod
    def _artifact_source_context_by_path(state: AgentState) -> dict[str, str]:
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return artifact_repair_contracts.source_context_by_path(state.task)
        return dict(contract.source_context_by_path or {})

    @staticmethod
    def _artifact_source_text_for_path(state: AgentState, path: str) -> str:
        base_source = LLMDecisionPolicy._artifact_swe_base_source_text(state, path)
        if base_source:
            return base_source
        candidates = LLMDecisionPolicy._artifact_source_text_candidates_for_path(state, path)
        return candidates[0] if candidates else ""

    @staticmethod
    def _artifact_source_lines_for_operation(
        state: AgentState,
        spec: dict[str, object],
        start_line: int,
        end_line: int,
    ) -> list[str]:
        path = str(spec.get("path") or "").strip().strip("/")
        if not path or start_line < 1 or end_line < start_line:
            return []
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        if not source_text:
            return []
        lines = source_text.splitlines()
        if end_line > len(lines):
            return []
        return lines[int(start_line) - 1 : int(end_line)]

    @staticmethod
    def _artifact_python_source_text_for_path(state: AgentState, path: str) -> str:
        base_source = LLMDecisionPolicy._artifact_swe_base_source_text(state, path)
        if base_source:
            if not LLMDecisionPolicy._artifact_python_compile_error(
                base_source,
                str(path).strip().strip("/"),
            ):
                return base_source
        candidates = LLMDecisionPolicy._artifact_source_text_candidates_for_path(state, path)
        if not candidates:
            return ""
        if not str(path).strip().endswith(".py"):
            return candidates[0]
        for candidate in candidates:
            if LLMDecisionPolicy._artifact_python_compile_error(candidate, str(path).strip().strip("/")):
                continue
            return candidate
        return candidates[0]

    @staticmethod
    def _artifact_python_compile_error(source_text: str, filename: str) -> str:
        try:
            compile(source_text, filename or "<artifact-source>", "exec")
        except SyntaxError as exc:
            location = f" line {exc.lineno}" if exc.lineno else ""
            return f"{exc.msg}{location}".strip()
        return ""

    @staticmethod
    def _artifact_source_text_candidates_for_path(state: AgentState, path: str) -> list[str]:
        normalized_path = str(path).strip().strip("/")
        if not normalized_path:
            return []
        candidates: list[str] = []

        def add_candidate(value: object) -> None:
            if not isinstance(value, str) or not value:
                return
            if value not in candidates:
                candidates.append(value)

        add_candidate(LLMDecisionPolicy._artifact_source_context_by_path(state).get(normalized_path, ""))
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        setup_file_contents = metadata.get("setup_file_contents", {})
        if not isinstance(setup_file_contents, dict):
            setup_file_contents = {}
        add_candidate(setup_file_contents.get(normalized_path))
        add_candidate(setup_file_contents.get(f"source_context/{normalized_path}"))
        workspace_subdir = str(getattr(state.task, "workspace_subdir", "") or "").strip()
        if workspace_subdir:
            for workspace_root in (Path(workspace_subdir), Path.cwd() / workspace_subdir):
                source_path = workspace_root / normalized_path
                try:
                    if source_path.is_file():
                        add_candidate(source_path.read_text(encoding="utf-8"))
                        break
                except OSError:
                    continue
        repo_cache_root = str(metadata.get("swe_repo_cache_root", "") or "").strip()
        swe_repo = str(metadata.get("swe_repo", "") or "").strip().strip("/")
        if repo_cache_root and swe_repo:
            repo_cache_path = Path(repo_cache_root) / swe_repo / normalized_path
            try:
                if repo_cache_path.is_file():
                    add_candidate(repo_cache_path.read_text(encoding="utf-8"))
            except OSError:
                pass
        line_numbered = setup_file_contents.get(f"source_lines/{normalized_path}.lines")
        if isinstance(line_numbered, str):
            extracted: list[str] = []
            for raw_line in line_numbered.splitlines():
                match = re.match(r"\s*\d+:\s?(.*)$", raw_line)
                extracted.append(match.group(1) if match else raw_line)
            add_candidate("\n".join(extracted) + ("\n" if extracted else ""))
        return candidates

    @staticmethod
    def _artifact_swe_repo_cache_path(repo_cache_root: str, repo: str) -> Path | None:
        root = Path(repo_cache_root)
        candidates = [
            root / repo,
            root / repo.replace("/", "__"),
            root / repo.split("/")[-1],
        ]
        for candidate in candidates:
            if candidate.exists() and candidate.is_dir():
                return candidate
        return None

    @classmethod
    def _artifact_swe_base_source_text(cls, state: AgentState, path: str) -> str:
        normalized_path = str(path).strip().strip("/")
        if not normalized_path.endswith(".py"):
            return ""
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        verifier = metadata.get("semantic_verifier", {})
        if not isinstance(verifier, dict):
            return ""
        if verifier.get("kind") != "swe_patch_apply_check":
            return ""
        repo = str(verifier.get("repo", "")).strip()
        base_commit = str(verifier.get("base_commit", "")).strip()
        repo_cache_root = str(verifier.get("repo_cache_root", "")).strip()
        if not repo or not base_commit or not repo_cache_root:
            return ""
        repo_path = cls._artifact_swe_repo_cache_path(repo_cache_root, repo)
        if repo_path is None:
            return ""
        result = subprocess.run(
            ["git", "-C", str(repo_path), "show", f"{base_commit}:{normalized_path}"],
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            check=False,
        )
        if result.returncode != 0:
            return ""
        return result.stdout

    @staticmethod
    def _artifact_source_line_numbers_for_path(state: AgentState, path: str) -> list[int]:
        normalized_path = str(path).strip().strip("/")
        if not normalized_path:
            return []
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        setup_file_contents = metadata.get("setup_file_contents", {})
        numbers: list[int] = []
        seen: set[int] = set()
        if isinstance(setup_file_contents, dict):
            line_numbered = setup_file_contents.get(f"source_lines/{normalized_path}.lines")
            if isinstance(line_numbered, str):
                for raw_line in line_numbered.splitlines():
                    match = re.match(r"\s*(\d+):", raw_line)
                    if not match:
                        continue
                    value = int(match.group(1))
                    if value in seen:
                        continue
                    seen.add(value)
                    numbers.append(value)
        edit_windows = str(
            metadata.get("artifact_executable_edit_windows")
            or metadata.get("swe_executable_edit_windows")
            or ""
        )
        active_section_matches = not normalized_path
        for raw_line in edit_windows.splitlines():
            header = re.match(r"\s*###\s+([^:]+)::", raw_line)
            if header:
                active_section_matches = str(header.group(1)).strip().strip("/") == normalized_path
                if active_section_matches:
                    range_match = re.search(r"\blines\s+(\d+)\s*-\s*(\d+)\b", raw_line)
                    if range_match:
                        for raw_value in range_match.groups():
                            value = int(raw_value)
                            if value in seen:
                                continue
                            seen.add(value)
                            numbers.append(value)
                continue
            if not active_section_matches:
                continue
            match = re.match(r"\s*(\d+):", raw_line)
            if not match:
                continue
            value = int(match.group(1))
            if value in seen:
                continue
            seen.add(value)
            numbers.append(value)
        return numbers

    @staticmethod
    def _artifact_source_lines_by_number(state: AgentState, path: str) -> dict[int, str]:
        normalized_path = str(path).strip().strip("/")
        if not normalized_path:
            return {}
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        setup_file_contents = metadata.get("setup_file_contents", {})
        if isinstance(setup_file_contents, dict):
            line_numbered = setup_file_contents.get(f"source_lines/{normalized_path}.lines")
            if isinstance(line_numbered, str):
                by_number: dict[int, str] = {}
                for raw_line in line_numbered.splitlines():
                    match = re.match(r"\s*(\d+):\s?(.*)$", raw_line)
                    if not match:
                        continue
                    by_number[int(match.group(1))] = match.group(2)
                if by_number:
                    candidates = sorted(
                        LLMDecisionPolicy._artifact_source_text_candidates_for_path(state, normalized_path),
                        key=lambda value: len(value.splitlines()),
                        reverse=True,
                    )
                    for candidate in candidates:
                        candidate_lines = candidate.splitlines()
                        if len(candidate_lines) <= len(by_number):
                            continue
                        for index, line in enumerate(candidate_lines, start=1):
                            by_number.setdefault(index, line)
                        break
                    return by_number
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, normalized_path)
        if not source_text:
            return {}
        return {index: line for index, line in enumerate(source_text.splitlines(), start=1)}

    @staticmethod
    def _format_replacement_like_builder(
        source_lines: list[str],
        *,
        start_line: int,
        replacement_lines: list[str],
    ) -> list[str]:
        formatted: list[str] = []
        for offset, replacement in enumerate(replacement_lines):
            line = replacement if str(replacement).endswith("\n") else f"{replacement}\n"
            original_index = start_line - 1 + offset
            if original_index < len(source_lines) and line.strip() and not line[:1].isspace():
                original_indent = ""
                for char in source_lines[original_index]:
                    if char not in {" ", "\t"}:
                        break
                    original_indent += char
                if original_indent:
                    line = f"{original_indent}{line}"
            elif (
                original_index < len(source_lines)
                and line.strip()
                and line.startswith(" ")
                and not line.startswith("  ")
            ):
                original_indent = ""
                for char in source_lines[original_index]:
                    if char not in {" ", "\t"}:
                        break
                    original_indent += char
                if len(original_indent) >= 2:
                    line = f"{original_indent}{line.lstrip()}"
            formatted.append(line)
        return formatted

    @staticmethod
    def _artifact_builder_replaces_existing_source(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return False
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        if not source_text:
            return False
        source_lines = source_text.splitlines(keepends=True)
        operations = list(spec.get("operations", []))
        if not operations:
            return False
        for start_line, end_line, replacement_lines in operations:
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                return False
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=start_line,
                replacement_lines=list(replacement_lines),
            )
            original = source_lines[start_line - 1 : end_line]
            if [line.rstrip("\n") for line in formatted] != [line.rstrip("\n") for line in original]:
                return False
        return True

    @staticmethod
    def _artifact_duplicate_line_guard_candidate(line: str) -> bool:
        stripped = str(line).strip()
        if len(stripped) < 8:
            return False
        if stripped.startswith(("#", "@", "\"", "'", ")", "]", "}")):
            return False
        if stripped in {"pass", "break", "continue"}:
            return False
        return True

    @staticmethod
    def _artifact_builder_introduces_adjacent_duplicate_line(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return False
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return False
        source_lines = source_text.splitlines(keepends=True)
        if not source_lines:
            return False
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                continue
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=int(start_line),
                replacement_lines=list(replacement_lines),
            )
            formatted_stripped = [
                str(line).strip()
                for line in formatted
                if LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(str(line))
            ]
            if not formatted_stripped:
                continue
            neighbors: set[str] = set()
            if int(start_line) > 1:
                before = source_lines[int(start_line) - 2].strip()
                if LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(before):
                    neighbors.add(before)
            if int(end_line) < len(source_lines):
                after = source_lines[int(end_line)].strip()
                if LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(after):
                    neighbors.add(after)
            if any(line in neighbors for line in formatted_stripped):
                return True
            for left, right in zip(formatted_stripped, formatted_stripped[1:]):
                if left == right:
                    return True
        return False

    @staticmethod
    def _artifact_builder_introduces_self_at_class_scope(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py") or _is_python_test_path(path):
            return False
        source_by_number = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        if not source_by_number:
            return False
        for start_line, _end_line, replacement_lines in spec.get("operations", []):
            if not any("self." in str(line) for line in replacement_lines):
                continue
            try:
                start = int(start_line)
            except (TypeError, ValueError):
                continue
            source_line = str(source_by_number.get(start, ""))
            if not source_line.strip():
                continue
            target_indent = len(source_line) - len(source_line.lstrip(" \t"))
            if target_indent <= 0:
                continue
            nearest_scope = ""
            for line_number in range(start - 1, 0, -1):
                line = str(source_by_number.get(line_number, ""))
                if not line.strip():
                    continue
                stripped = line.lstrip(" \t")
                indent = len(line) - len(stripped)
                if indent >= target_indent:
                    continue
                if stripped.startswith(("def ", "async def ", "class ")):
                    nearest_scope = stripped
                    break
            if nearest_scope.startswith("class "):
                return True
        return False

    @staticmethod
    def _artifact_builder_duplicates_nearby_python_statement(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py") or _is_python_test_path(path):
            return False
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return False
        source_lines = source_text.splitlines()
        if not source_lines:
            return False
        ignored_prefixes = (
            "def ",
            "async def ",
            "class ",
            "import ",
            "from ",
            "@",
            "#",
            "return ",
            "raise ",
        )
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            try:
                start = int(start_line)
                end = int(end_line)
            except (TypeError, ValueError):
                continue
            if start < 1 or end < start:
                continue
            window_start = max(1, start - 12)
            window_end = min(len(source_lines), end + 12)
            protected_span = set(range(start, end + 1))
            nearby_existing = {
                source_lines[line_number - 1].strip()
                for line_number in range(window_start, window_end + 1)
                if line_number not in protected_span
                and LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(source_lines[line_number - 1])
            }
            for replacement in LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines):
                stripped = str(replacement).strip()
                if not LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(stripped):
                    continue
                if stripped.startswith(ignored_prefixes):
                    continue
                if stripped in nearby_existing:
                    return True
        return False

    @staticmethod
    def _artifact_builder_narrow_multiline_duplicates_existing_context(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return False
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return False
        source_lines = source_text.splitlines()
        if not source_lines:
            return False
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            source_span = int(end_line) - int(start_line) + 1
            expanded_replacement_lines = [
                str(line).strip()
                for line in LLMDecisionPolicy._artifact_expanded_replacement_lines(replacement_lines)
                if LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(str(line))
            ]
            if source_span >= 3 or len(expanded_replacement_lines) < 3:
                continue
            window_start = max(1, int(start_line) - 12)
            window_end = min(len(source_lines), int(end_line) + 12)
            protected_span = set(range(int(start_line), int(end_line) + 1))
            nearby_existing = {
                source_lines[line_number - 1].strip()
                for line_number in range(window_start, window_end + 1)
                if line_number not in protected_span
                and LLMDecisionPolicy._artifact_duplicate_line_guard_candidate(source_lines[line_number - 1])
            }
            duplicate_count = sum(1 for line in expanded_replacement_lines if line in nearby_existing)
            if duplicate_count >= 2:
                return True
        return False

    @staticmethod
    def _artifact_builder_python_source_pair(
        state: AgentState,
        command: str,
    ) -> tuple[str, str, str]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return "", "", ""
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return "", "", ""
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return "", "", ""
        if LLMDecisionPolicy._artifact_python_compile_error(source_text, path):
            return "", "", ""
        source_lines = source_text.splitlines(keepends=True)
        updated_lines = list(source_lines)
        operations = sorted(list(spec.get("operations", [])), key=lambda item: int(item[0]), reverse=True)
        for start_line, end_line, replacement_lines in operations:
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                return "", "", ""
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=int(start_line),
                replacement_lines=list(replacement_lines),
            )
            updated_lines[int(start_line) - 1 : int(end_line)] = formatted
        updated_source = "".join(updated_lines)
        if LLMDecisionPolicy._artifact_python_compile_error(updated_source, path):
            return "", "", ""
        return path, source_text, updated_source

    @staticmethod
    def _artifact_builder_python_ast_unchanged(state: AgentState, command: str) -> bool:
        path, before_source, after_source = LLMDecisionPolicy._artifact_builder_python_source_pair(state, command)
        if not path or before_source == after_source:
            return False
        return not _python_executable_ast_changed(before_source, after_source)

