    @staticmethod
    def _artifact_builder_suspicious_statement_replacement_details(
        state: AgentState,
        command: str,
    ) -> list[str]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py") or _is_python_test_path(path):
            return []
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return []
        source_lines = source_text.splitlines()
        details: list[str] = []
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                continue
            original = source_lines[int(start_line) - 1 : int(end_line)]
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                [line + "\n" for line in source_lines],
                start_line=int(start_line),
                replacement_lines=list(replacement_lines),
            )
            if len(original) == 1 and len(formatted) == 1:
                replacement_stripped = str(formatted[0]).strip()
                original_stripped = str(original[0]).strip()
                if replacement_stripped and replacement_stripped != original_stripped:
                    for source_index, source_line in enumerate(source_lines, start=1):
                        if source_index == int(start_line):
                            continue
                        if abs(source_index - int(start_line)) <= 20:
                            continue
                        if str(source_line).strip() == replacement_stripped:
                            details.append(
                                "replacement transplants an existing distant source line "
                                f"{source_index} into line {int(start_line)}"
                            )
                            break
            if (
                len(original) == 1
                and len(formatted) == 1
                and LLMDecisionPolicy._artifact_python_line_shape_compatible(original[0], formatted[0])
            ):
                continue
            details.extend(
                _python_suspicious_line_replacement_details(
                    [line.rstrip("\n") for line in original],
                    [line.rstrip("\n") for line in formatted],
                )
            )
        return details

    @staticmethod
    def _artifact_builder_has_placeholder_output_replacement(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            source_lines = LLMDecisionPolicy._artifact_source_lines_for_operation(state, spec, start_line, end_line)
            added = [str(line).strip() for line in replacement_lines if str(line).strip()]
            removed = [str(line).strip() for line in source_lines if str(line).strip()]
            if not added or not removed:
                continue
            has_placeholder_output = any(
                re.search(
                    r"^(print|click\.echo|click\.secho|logger\.\w+)\(\s*['\"](?:patch (?:applied|works|done|fixed)|success|done|fixed)['\"]",
                    line,
                    flags=re.IGNORECASE,
                )
                for line in added
            )
            if not has_placeholder_output:
                continue
            if any(re.match(r"^print\(\s*['\"](?:patch applied|success|done|fixed|works)['\"]\s*\)\s*$", line, flags=re.IGNORECASE) for line in added):
                return True
            if any(
                re.search(
                    r"\b(exception|error|warning|failed|raise|return|logger|click\.secho|click\.echo)\b",
                    line,
                    flags=re.IGNORECASE,
                )
                for line in removed
            ):
                return True
        return False

    @staticmethod
    def _artifact_builder_introduced_self_recursive_property_accesses(state: AgentState, command: str) -> list[str]:
        path, before_source, after_source = LLMDecisionPolicy._artifact_builder_python_source_pair(state, command)
        if not path or _is_python_test_path(path):
            return []
        return _python_introduced_self_recursive_property_accesses(before_source, after_source)

    @staticmethod
    def _artifact_builder_introduced_self_recursive_method_calls(state: AgentState, command: str) -> list[str]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py") or _is_python_test_path(path):
            return []
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text or LLMDecisionPolicy._artifact_python_compile_error(source_text, path):
            return []
        try:
            tree = ast.parse(source_text)
        except SyntaxError:
            return []
        details: list[str] = []
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if int(start_line) < 1 or int(end_line) < int(start_line):
                continue
            enclosing_name = ""
            enclosing_span = 10**9
            for node in ast.walk(tree):
                if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                node_start = int(getattr(node, "lineno", 0) or 0)
                node_end = int(getattr(node, "end_lineno", node_start) or node_start)
                if node_start <= int(start_line) <= node_end:
                    span = node_end - node_start
                    if span < enclosing_span:
                        enclosing_name = str(node.name)
                        enclosing_span = span
            if not enclosing_name:
                continue
            replacement_text = "\n".join(str(line).rstrip("\n") for line in replacement_lines)
            pattern = rf"\b(?:self|cls)\s*\.\s*{re.escape(enclosing_name)}\s*\("
            if re.search(pattern, replacement_text):
                details.append(f"{path}:{int(start_line)}-{int(end_line)} introduces self/cls.{enclosing_name}() inside {enclosing_name}()")
        return details

    @staticmethod
    def _artifact_builder_nested_assignment_replacement_details(state: AgentState, command: str) -> list[str]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py") or _is_python_test_path(path):
            return []
        source_lines = LLMDecisionPolicy._artifact_source_lines_by_number(state, path)
        if not source_lines:
            return []
        patch_lines = [f"+++ b/{path}"]
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line:
                continue
            patch_lines.append("@@")
            for line_number in range(int(start_line), int(end_line) + 1):
                if line_number in source_lines:
                    patch_lines.append("-" + source_lines[line_number])
            for line in replacement_lines:
                patch_lines.append("+" + str(line))
        return _python_nested_assignment_replacement_details("\n".join(patch_lines))

