    @staticmethod
    def _artifact_builder_one_line_open_call_replacement(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        operations = list(spec.get("operations", []))
        if len(operations) != 1:
            return False
        start_line, end_line, replacement_lines = operations[0]
        if int(start_line) != int(end_line) or len(replacement_lines) != 1:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return False
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        source_lines = source_text.splitlines()
        if not source_lines or int(start_line) < 1 or int(start_line) > len(source_lines):
            return False
        old_line = source_lines[int(start_line) - 1].strip()
        new_line = str(replacement_lines[0]).strip()
        if not old_line or not new_line or old_line == new_line:
            return False
        if not new_line.endswith("("):
            return False
        # A one-line replacement that opens a call normally borrows unrelated
        # continuation lines from the old expression and passes local apply checks
        # while changing call arity/semantics nonsensically.
        return bool(re.search(r"=\s*[A-Za-z_][A-Za-z0-9_.]*\($", new_line))

