    @staticmethod
    def _artifact_source_identical_operation_details(state: AgentState, command: str) -> list[dict[str, object]]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        if not path:
            return []
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        if not source_text:
            return []
        source_lines = source_text.splitlines(keepends=True)
        details: list[dict[str, object]] = []
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                continue
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=start_line,
                replacement_lines=list(replacement_lines),
            )
            original = source_lines[start_line - 1 : end_line]
            if [line.rstrip("\n") for line in formatted] != [line.rstrip("\n") for line in original]:
                continue
            existing_source = "\n".join(line.rstrip("\n") for line in original)
            rejected_replacement = "\n".join(line.rstrip("\n") for line in formatted)
            detail: dict[str, object] = {
                "path": path,
                "start_line": int(start_line),
                "end_line": int(end_line),
                "existing_source": existing_source[:800],
                "rejected_replacement": rejected_replacement[:800],
            }
            if path.endswith(".py"):
                source_text_plain = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path) or "".join(
                    source_lines
                )
                statement_range = LLMDecisionPolicy._artifact_python_statement_range(
                    source_text_plain,
                    target_line=int(start_line),
                )
                if statement_range:
                    suggested_start = int(statement_range.get("start_line", start_line) or start_line)
                    suggested_end = int(statement_range.get("end_line", end_line) or end_line)
                    plain_lines = [line.rstrip("\n") for line in source_lines]
                    detail["suggested_statement_range"] = statement_range
                    detail["suggested_existing_source"] = "\n".join(
                        plain_lines[suggested_start - 1 : suggested_end]
                    )[:1200]
                    context_start = max(1, suggested_start - 3)
                    context_end = min(len(plain_lines), suggested_end + 3)
                    detail["nearby_source_context"] = "\n".join(
                        f"{line_no}: {plain_lines[line_no - 1]}"
                        for line_no in range(context_start, context_end + 1)
                    )[:1600]
            details.append(detail)
        return details

    @staticmethod
    def _artifact_python_statement_range(source_text: str, *, target_line: int) -> dict[str, object]:
        try:
            tree = ast.parse(source_text)
        except SyntaxError:
            return {}
        best: tuple[int, int, str] | None = None
        for node in ast.walk(tree):
            if not isinstance(node, (ast.stmt, ast.ExceptHandler)):
                continue
            start = getattr(node, "lineno", None)
            end = getattr(node, "end_lineno", None)
            if not isinstance(start, int) or not isinstance(end, int):
                continue
            if start <= target_line <= end:
                candidate = (start, end, node.__class__.__name__)
                if best is None or (candidate[1] - candidate[0], candidate[0]) < (best[1] - best[0], best[0]):
                    best = candidate
        if best is None:
            return {}
        return {
            "start_line": best[0],
            "end_line": best[1],
            "node_type": best[2],
        }

    @staticmethod
    def _artifact_invalid_python_replacement_details(state: AgentState, command: str) -> list[dict[str, object]]:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return []
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return []
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return []
        if LLMDecisionPolicy._artifact_python_compile_error(source_text, path):
            return []
        source_lines = source_text.splitlines()
        source_lines_keepends = source_text.splitlines(keepends=True)
        updated_lines = list(source_lines_keepends)
        operations = sorted(list(spec.get("operations", [])), key=lambda item: int(item[0]), reverse=True)
        for start_line, end_line, replacement_lines in operations:
            if start_line < 1 or end_line < start_line or end_line > len(source_lines_keepends):
                return []
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines_keepends,
                start_line=start_line,
                replacement_lines=list(replacement_lines),
            )
            updated_lines[start_line - 1 : end_line] = formatted
        syntax_error = LLMDecisionPolicy._artifact_python_compile_error("".join(updated_lines), path)
        if not syntax_error:
            return []
        details: list[dict[str, object]] = []
        for start_line, end_line, replacement_lines in spec.get("operations", []):
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                continue
            statement_range = LLMDecisionPolicy._artifact_python_statement_range(
                source_text,
                target_line=int(start_line),
            )
            suggested_start = int(statement_range.get("start_line", start_line) or start_line)
            suggested_end = int(statement_range.get("end_line", end_line) or end_line)
            existing_source = "\n".join(source_lines[suggested_start - 1 : suggested_end])
            attempted_existing_source = "\n".join(source_lines[int(start_line) - 1 : int(end_line)])
            replacement_preview = "\n".join(str(line).rstrip("\n") for line in replacement_lines)
            first_replacement = ""
            for line in replacement_lines:
                first_replacement = str(line).strip()
                if first_replacement:
                    break
            first_existing = source_lines[int(start_line) - 1].strip() if source_lines else ""
            statement_keyword_prefixes = (
                "def ",
                "async def ",
                "class ",
                "return ",
                "if ",
                "for ",
                "while ",
                "try:",
                "with ",
                "import ",
                "from ",
            )
            detail: dict[str, object] = {
                "path": path,
                "attempted_start_line": int(start_line),
                "attempted_end_line": int(end_line),
                "attempted_existing_source": attempted_existing_source[:800],
                "syntax_error": syntax_error[:400],
                "replacement_line_count": len(list(replacement_lines)),
                "replacement_preview": replacement_preview[:800],
            }
            if statement_range:
                detail["suggested_statement_range"] = statement_range
                detail["suggested_existing_source"] = existing_source[:1200]
                statement_span = suggested_end - suggested_start + 1
                if statement_span > 8:
                    detail["large_enclosing_statement"] = True
                    detail["recommended_repair_shape"] = (
                        "Use a narrow syntactically valid expression/argument replacement at the original "
                        "indentation, or choose a smaller complete statement inside the same edit window; do "
                        "not replace the whole broad enclosing statement unless necessary."
                    )
            if (
                first_replacement.startswith(statement_keyword_prefixes)
                and first_existing
                and not first_existing.startswith(statement_keyword_prefixes)
            ):
                detail["replacement_syntax_kind_mismatch"] = {
                    "existing_line": first_existing[:400],
                    "replacement_first_line": first_replacement[:400],
                    "repair_hint": (
                        "Replacement starts with a statement header/keyword but the target line is an "
                        "expression or continuation line; replace it with the same syntactic kind or choose "
                        "a complete statement range."
                    ),
                }
            details.append(detail)
        return details

    @staticmethod
    def _artifact_builder_would_produce_invalid_python(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".py"):
            return False
        source_text = LLMDecisionPolicy._artifact_python_source_text_for_path(state, path)
        if not source_text:
            return False
        if LLMDecisionPolicy._artifact_python_compile_error(source_text, path):
            return False
        source_lines = source_text.splitlines(keepends=True)
        updated_lines = list(source_lines)
        operations = sorted(list(spec.get("operations", [])), key=lambda item: int(item[0]), reverse=True)
        for start_line, end_line, replacement_lines in operations:
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                return False
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=start_line,
                replacement_lines=list(replacement_lines),
            )
            updated_lines[start_line - 1 : end_line] = formatted
        if LLMDecisionPolicy._artifact_python_compile_error("".join(updated_lines), path):
            return True
        return False

    @staticmethod
    def _artifact_builder_would_produce_invalid_json(state: AgentState, command: str) -> bool:
        spec = LLMDecisionPolicy._artifact_builder_command_spec(state, command, require_redirect=False)
        if spec is None:
            return False
        path = str(spec.get("path") or "").strip().strip("/")
        if not path.endswith(".json"):
            return False
        source_text = LLMDecisionPolicy._artifact_source_text_for_path(state, path)
        if not source_text:
            return False
        try:
            json.loads(source_text)
        except json.JSONDecodeError:
            return False
        source_lines = source_text.splitlines(keepends=True)
        updated_lines = list(source_lines)
        operations = sorted(list(spec.get("operations", [])), key=lambda item: int(item[0]), reverse=True)
        for start_line, end_line, replacement_lines in operations:
            if start_line < 1 or end_line < start_line or end_line > len(source_lines):
                return False
            formatted = LLMDecisionPolicy._format_replacement_like_builder(
                source_lines,
                start_line=start_line,
                replacement_lines=list(replacement_lines),
            )
            updated_lines[start_line - 1 : end_line] = formatted
        try:
            json.loads("".join(updated_lines))
        except json.JSONDecodeError:
            return True
        return False

    def _artifact_prior_source_inspection_count(self, state: AgentState) -> int:
        count = 0
        for step in state.history:
            if step.action != CODE_EXECUTE:
                continue
            content = str(step.content).strip()
            if self._artifact_non_materializing_repair_command(state, content) and not self._artifact_materializes(
                state,
                content,
            ):
                count += 1
        if self._artifact_last_backoff_has_source_inspection_evidence(state):
            count += 1
        return count

    def _artifact_prior_source_lines_inspection_count(self, state: AgentState) -> int:
        count = 0
        for step in state.history:
            if step.action != CODE_EXECUTE:
                continue
            if self._artifact_source_lines_inspection_command(str(step.content)):
                count += 1
        if self._artifact_last_backoff_has_source_lines_evidence(state):
            count += 1
        return count

    @staticmethod
    def _artifact_last_backoff_evidence(state: AgentState) -> list[str]:
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        last_backoff_failure = metadata.get("artifact_last_backoff_failure")
        if not isinstance(last_backoff_failure, dict):
            return []
        evidence = last_backoff_failure.get("evidence", [])
        if not isinstance(evidence, list):
            return []
        return [str(item).strip() for item in evidence if str(item).strip()]

    @classmethod
    def _artifact_last_backoff_has_source_inspection_evidence(cls, state: AgentState) -> bool:
        return any(
            "source_lines_path:" in item
            or "source_context_path:" in item
            or str(item).startswith("decision_source:artifact_source_lines_followup")
            or str(item).startswith("decision_source:artifact_expected_behavior_source_lines_followup")
            for item in cls._artifact_last_backoff_evidence(state)
        )

    @classmethod
    def _artifact_last_backoff_has_source_lines_evidence(cls, state: AgentState) -> bool:
        return any("source_lines_path:" in item for item in cls._artifact_last_backoff_evidence(state))

    @classmethod
    def _artifact_last_backoff_retry_rejected_reason(cls, state: AgentState) -> str:
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        last_backoff_failure = metadata.get("artifact_last_backoff_failure")
        texts: list[str] = []
        if isinstance(last_backoff_failure, dict):
            texts.append(str(last_backoff_failure.get("backoff_reason", "")))
        texts.extend(cls._artifact_last_backoff_evidence(state))
        for text in reversed(texts):
            match = re.search(r"retry_rejected_reason:([A-Za-z0-9_\\-]+)", str(text))
            if match:
                return match.group(1).strip()
        return ""

    def _artifact_source_inspection_allowed_after_history(self, state: AgentState, command: str) -> bool:
        normalized = str(command).strip()
        if not artifact_repair_contracts.command_is_source_inspection(normalized):
            return False
        if self._artifact_materializes(state, normalized):
            return False
        prior_source_inspections = self._artifact_prior_source_inspection_count(state)
        if prior_source_inspections < 1:
            return True
        if (
            prior_source_inspections == 1
            and self._artifact_source_lines_inspection_command(normalized)
            and self._artifact_prior_source_lines_inspection_count(state) < 1
        ):
            return True
        if self._artifact_source_lines_inspection_command(normalized):
            source_path = self._artifact_source_path_from_inspection_command(normalized)
            editable_paths = self._artifact_editable_patch_source_paths(
                list(self._artifact_source_context_by_path(state).keys())
            )
            if (
                self._artifact_editable_patch_source_path(source_path, editable_paths)
                and self._artifact_prior_editable_source_lines_inspection_count(state) < 1
            ):
                return True
        return False

    @staticmethod
    def _artifact_source_lines_inspection_command(command: str) -> bool:
        normalized = str(command).strip()
        return (
            artifact_repair_contracts.command_is_source_inspection(normalized)
            and "source_lines/" in normalized
            and ".lines" in normalized
        )

    def _artifact_prior_editable_source_lines_inspection_count(self, state: AgentState) -> int:
        editable_paths = self._artifact_editable_patch_source_paths(
            list(self._artifact_source_context_by_path(state).keys())
        )
        count = 0
        for step in state.history:
            if step.action != CODE_EXECUTE:
                continue
            command = str(step.content).strip()
            if not self._artifact_source_lines_inspection_command(command):
                continue
            source_path = self._artifact_source_path_from_inspection_command(command)
            if self._artifact_editable_patch_source_path(source_path, editable_paths):
                count += 1
        for item in self._artifact_last_backoff_evidence(state):
            if "source_lines_path:" not in item:
                continue
            source_path = item.split("source_lines_path:", 1)[1].strip()
            source_path = source_path.removeprefix("source_lines/").removesuffix(".lines").strip("/")
            if self._artifact_editable_patch_source_path(source_path, editable_paths):
                count += 1
        return count

    def _artifact_source_lines_followup_direct_decision(self, state: AgentState) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        if self._artifact_prior_source_lines_inspection_count(state) > 0:
            return None
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        edit_windows = str(
            metadata.get("artifact_executable_edit_windows")
            or metadata.get("swe_executable_edit_windows")
            or ""
        ).strip()
        source_context = self._artifact_source_context_by_path(state)
        source_paths = [path for path in source_context.keys() if path]
        source_path = (
            self._artifact_last_builder_source_path(state)
            or self._artifact_preferred_edit_window_source_path(
                state,
                source_paths=source_paths,
                edit_windows=edit_windows,
            )
            or self._artifact_last_inspected_source_path(state)
            or self._artifact_preferred_production_source_path(source_paths)
            or (source_paths[0] if source_paths else "")
        )
        if not source_path:
            return None
        source_lines_path = f"source_lines/{source_path}.lines"
        if not self._artifact_setup_file_available(state, source_lines_path):
            return None
        reason = (
            "after a no-op artifact repair"
            if self._artifact_noop_repair_context(state)
            else "after source inspection with missing-artifact verifier feedback"
        )
        return ActionDecision(
            thought=f"Read line-numbered source {reason} so the next edit has exact anchors.",
            action=CODE_EXECUTE,
            content=f"cat {shlex.quote(source_lines_path)}",
            done=False,
            decision_source="artifact_source_lines_followup_direct",
            proposal_metadata={
                "artifact_source_lines_followup": True,
                "source_path": source_path,
                "source_lines_path": source_lines_path,
            },
        )

    def _artifact_expected_behavior_source_lines_followup_direct_decision(
        self,
        state: AgentState,
    ) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        if self._artifact_prior_source_lines_inspection_count(state) < 1:
            return None
        if any(
            str(step.decision_source).strip() == "artifact_expected_behavior_source_lines_followup_direct"
            for step in state.history
        ):
            return None

        inspected_paths: set[str] = set()
        for step in state.history:
            if step.action != CODE_EXECUTE:
                continue
            command = str(step.content).strip()
            if not self._artifact_source_lines_inspection_command(command):
                continue
            source_path = self._artifact_source_path_from_inspection_command(command)
            if source_path:
                inspected_paths.add(source_path)

        source_context = self._artifact_source_context_by_path(state)
        source_paths = [path for path in source_context.keys() if path]
        candidate_paths = [
            path
            for path in source_paths
            if _is_python_test_path(path)
            and path not in inspected_paths
            and self._artifact_setup_file_available(state, f"source_lines/{path}.lines")
        ]
        if not candidate_paths:
            return None

        prompt = str(state.task.prompt or "").lower()

        def score(path: str) -> tuple[int, int, int]:
            lowered = path.lower()
            basename = lowered.rsplit("/", 1)[-1]
            prompt_hits = sum(1 for token in re.split(r"[^a-z0-9_]+", basename) if token and token in prompt)
            unit_score = 1 if "test" in basename else 0
            return (prompt_hits, unit_score, -len(path))

        source_path = max(candidate_paths, key=score)
        source_lines_path = f"source_lines/{source_path}.lines"
        return ActionDecision(
            thought=(
                "Read line-numbered expected-behavior source before patch synthesis so the repair has "
                "both editable anchors and verifier intent."
            ),
            action=CODE_EXECUTE,
            content=f"cat {shlex.quote(source_lines_path)}",
            done=False,
            decision_source="artifact_expected_behavior_source_lines_followup_direct",
            proposal_metadata={
                "artifact_expected_behavior_source_lines_followup": True,
                "source_path": source_path,
                "source_lines_path": source_lines_path,
            },
        )

    def _artifact_last_inspected_source_path(self, state: AgentState) -> str:
        known_sources = set(self._artifact_source_context_by_path(state).keys())
        for step in reversed(state.history):
            if step.action != CODE_EXECUTE:
                continue
            command = str(step.content).strip()
            if self._artifact_source_lines_inspection_command(command):
                continue
            if not artifact_repair_contracts.command_is_source_inspection(command):
                continue
            path = self._artifact_source_path_from_inspection_command(command)
            if path and (not known_sources or path in known_sources):
                return path
        return ""

    @staticmethod
    def _artifact_source_path_from_inspection_command(command: str) -> str:
        try:
            parts = shlex.split(str(command).strip())
        except ValueError:
            return ""
        if not parts:
            return ""
        executable = parts[0]
        if executable not in artifact_repair_contracts.SOURCE_INSPECTION_EXECUTABLES:
            return ""
        candidates: list[str] = []
        for token in parts[1:]:
            candidate = str(token).strip().strip("'\"").strip("/")
            if not candidate or candidate.startswith("-"):
                continue
            if candidate.replace(",", "").replace("-", "").isdigit():
                continue
            if candidate.startswith("source_lines/") and candidate.endswith(".lines"):
                candidate = candidate.removeprefix("source_lines/").removesuffix(".lines").strip("/")
            elif candidate.startswith("source_context/"):
                candidate = candidate.removeprefix("source_context/").strip("/")
            elif candidate in {".", "/"}:
                continue
            candidates.append(candidate)
        for candidate in candidates:
            if (
                candidate.endswith(".py")
                and not _is_python_test_path(candidate)
                and not _is_disallowed_swe_solution_path(candidate)
            ):
                return candidate
        return candidates[-1] if candidates else ""

    @classmethod
    def _artifact_last_builder_source_path(cls, state: AgentState) -> str:
        for step in reversed(state.history):
            if step.action != CODE_EXECUTE:
                continue
            spec = cls._artifact_builder_command_spec(state, str(step.content), require_redirect=False)
            if spec is None:
                continue
            path = str(spec.get("path", "")).strip().strip("/")
            if path:
                return path
        return ""

    @staticmethod
    def _artifact_setup_file_available(state: AgentState, path: str) -> bool:
        normalized = str(path).strip().strip("/")
        if not normalized:
            return False
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        setup_file_contents = metadata.get("setup_file_contents", {})
        if isinstance(setup_file_contents, dict) and normalized in {
            str(key).strip().strip("/") for key in setup_file_contents.keys()
        }:
            return True
        workflow_guard = metadata.get("workflow_guard", {})
        if isinstance(workflow_guard, dict):
            managed_paths = workflow_guard.get("managed_paths", [])
            if isinstance(managed_paths, list) and normalized in {
                str(item).strip().strip("/") for item in managed_paths
            }:
                return True
        return False

    @staticmethod
    def _artifact_repair_context(state: AgentState) -> bool:
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return False
        artifact_path = contract.artifact_path
        task = state.task
        if artifact_path in task.expected_files:
            return True
        return any(
            str(diagnosis.get("path", "")).strip() == artifact_path
            and (
                str(diagnosis.get("repair_instruction", "")).strip()
                or "verifier_failure" in [str(signal) for signal in diagnosis.get("signals", [])]
                or str(diagnosis.get("source_role", "")).strip() == "verifier"
            )
            for diagnosis in state.subgoal_diagnoses.values()
            if isinstance(diagnosis, dict)
        )

    @classmethod
    def _artifact_inference_failure_source_context_fallback(cls, state: AgentState) -> ActionDecision | None:
        if not LLMDecisionPolicy._artifact_latest_repairable_failure(state):
            return None
        recent_artifact_diagnostic_sources = {
            "artifact_broad_replacement_context_read",
            "artifact_candidate_set_exhausted_context_read",
            "artifact_candidate_cluster_reanchor_context_read",
            "artifact_candidate_cluster_reanchor_failed_context_read",
            "artifact_definition_header_context_read",
            "artifact_invalid_python_statement_context_read",
            "artifact_shallow_patch_context_read",
            "artifact_source_inspection_exhausted_context_read",
        }
        if any(str(step.decision_source).strip() in recent_artifact_diagnostic_sources for step in state.history[-3:]):
            return None
        prior_inference_fallbacks = sum(
            1
            for step in state.history
            if str(step.decision_source).strip() == "artifact_inference_failure_source_context_fallback"
        )
        if prior_inference_fallbacks >= 1:
            return None
        attempted = {
            str(step.content).strip()
            for step in state.history
            if step.action == CODE_EXECUTE and str(step.content).strip()
        }
        metadata = state.task.metadata if isinstance(state.task.metadata, dict) else {}
        setup_file_contents = metadata.get("setup_file_contents", {})
        if not isinstance(setup_file_contents, dict):
            return None

        edit_windows = str(
            metadata.get("artifact_executable_edit_windows")
            or metadata.get("swe_executable_edit_windows")
            or ""
        ).strip()
        source_context = cls._artifact_source_context_by_path(state)
        source_paths = [path for path in source_context.keys() if path]
        preferred_source_path = cls._artifact_preferred_edit_window_source_path(
            state,
            source_paths=source_paths,
            edit_windows=edit_windows,
        ) or cls._artifact_preferred_production_source_path(source_paths)

        candidate_paths: list[str] = []
        if preferred_source_path:
            candidate_paths.extend(
                [
                    f"source_lines/{preferred_source_path}.lines",
                    f"source_context/{preferred_source_path}",
                ]
            )

        production_source_paths = [
            path
            for path in source_paths
            if path.endswith(".py") and not _is_python_test_path(path) and not _is_disallowed_swe_solution_path(path)
        ]
        for source_path in production_source_paths:
            candidate_paths.extend([f"source_lines/{source_path}.lines", f"source_context/{source_path}"])

        # Once production/edit-window context exists, do not spend the only inference
        # fallback on tests/examples/docs. That usually reinforces expected behavior
        # but does not give the repair loop a better source anchor.
        if not preferred_source_path and not production_source_paths:
            for raw_path, content in setup_file_contents.items():
                if not isinstance(content, str):
                    continue
                path = str(raw_path).strip().strip("/")
                if path.startswith("source_lines/") and path.endswith(".lines"):
                    candidate_paths.append(path)
            for raw_path, content in setup_file_contents.items():
                if not isinstance(content, str):
                    continue
                path = str(raw_path).strip().strip("/")
                if path.startswith("source_context/"):
                    candidate_paths.append(path)

        seen: set[str] = set()
        for path in candidate_paths:
            if not path or path in seen or any(part == ".." for part in Path(path).parts):
                continue
            if path not in {str(key).strip().strip("/") for key in setup_file_contents.keys()}:
                continue
            seen.add(path)
            command = f"cat {shlex.quote(path)}"
            if command in attempted:
                continue
            return ActionDecision(
                thought=(
                    "Recover from an inference-format failure during artifact repair by reading "
                    "unattempted source context before asking the live model again."
                ),
                action=CODE_EXECUTE,
                content=command,
                done=False,
                decision_source="artifact_inference_failure_source_context_fallback",
                proposal_metadata={
                    "artifact_inference_failure_fallback": True,
                    "fallback_path": path,
                },
            )
        return None

    def _artifact_inference_failure_candidate_suggestion_direct_decision(self, state: AgentState) -> ActionDecision | None:
        if self._artifact_candidate_suggestions_suppressed_by_feedback(
            state,
            allow_official_regression_inference_retry=True,
        ):
            return None
        if not self._artifact_latest_repairable_failure(state):
            return None
        prior_inference_fallbacks = sum(
            1
            for step in state.history
            if str(step.decision_source).strip() == "artifact_inference_failure_source_context_fallback"
        )
        if prior_inference_fallbacks < 1:
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        candidate_records = self._artifact_placeholder_safe_candidate_records(
            list(artifact_repair_context.get("candidate_edit_records", []) or [])
        )
        if not path or not candidate_records:
            return None
        command = self._artifact_first_candidate_suggested_replacement_command(
            state,
            candidate_records=candidate_records,
            path=path,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        if not command:
            return None
        return ActionDecision(
            thought=(
                "Recover from repeated inference failures by using a guarded source-grounded "
                "candidate replacement command."
            ),
            action=CODE_EXECUTE,
            content=command,
            done=False,
            decision_source="artifact_inference_failure_candidate_suggestion_direct",
            proposal_metadata={
                "artifact_inference_failure_candidate_suggestion": True,
                "artifact_inference_failure_fallbacks": prior_inference_fallbacks,
                "artifact_candidate_path": path,
            },
        )

    def _artifact_inference_failure_after_shallow_source_context_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        recent_sources = [str(step.decision_source).strip() for step in state.history[-8:]]
        if "artifact_shallow_patch_context_read" not in recent_sources:
            return None
        if "artifact_source_inspection_exhausted_context_read" not in recent_sources:
            return None
        if "artifact_behavior_target_repair_context_read" in recent_sources:
            return None
        if any(
            str(step.decision_source).strip()
            == "artifact_inference_failure_after_shallow_source_context_read"
            for step in state.history[-10:]
        ):
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        shallow_command = ""
        for step in reversed(state.history):
            if str(step.decision_source).strip() != "artifact_shallow_patch_context_read":
                continue
            metadata = step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}
            shallow_command = str(metadata.get("retry_command", "")).strip()
            if shallow_command:
                break
        if not shallow_command:
            return None
        behavior_context = self._artifact_behavior_target_repair_context_read_decision(
            state,
            command=shallow_command,
            artifact_path=artifact_path,
            retry_attempt=0,
        )
        if behavior_context is None:
            return None
        behavior_context.decision_source = "artifact_inference_failure_after_shallow_source_context_read"
        behavior_context.thought = (
            "Recover from an inference failure after shallow-patch rejection by forcing a "
            "structured behavior-target repair packet."
        )
        behavior_context.proposal_metadata = {
            **dict(behavior_context.proposal_metadata or {}),
            "artifact_inference_failure_after_shallow_source_context_read": True,
            "retry_rejected_reason": "inference_failure_after_shallow_source_context",
            "inference_failure_error_text": str(error_text)[:300],
        }
        return behavior_context

    def _artifact_inference_failure_after_behavior_target_context_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        recent_sources = [str(step.decision_source).strip() for step in state.history[-8:]]
        if "artifact_behavior_target_repair_context_read" not in recent_sources:
            return None
        if any(
            str(step.decision_source).strip()
            == "artifact_inference_failure_after_behavior_target_context_read"
            for step in state.history[-10:]
        ):
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        candidate_records = [
            self._artifact_virtual_candidate_context_record(record)
            for record in self._artifact_placeholder_safe_candidate_records(
                list(artifact_repair_context.get("candidate_edit_records", []) or [])
            )[:12]
            if isinstance(record, dict)
        ]
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        if not artifact_repair_context and not candidate_records:
            return None
        context = {
            "mode": "inference_failure_after_behavior_target_repair_context",
            "artifact_path": artifact_path,
            "builder_command": builder_command,
            "path": path,
            "candidate_edit_records": candidate_records,
            "valid_line_numbers_preview": artifact_repair_context.get("valid_line_numbers_preview", []),
            "source_lines_excerpt": str(artifact_repair_context.get("source_lines_excerpt", ""))[:2200],
            "fail_to_pass_function_source_excerpts": artifact_repair_context.get(
                "fail_to_pass_function_source_excerpts",
                {},
            ),
            "action_failure_memory": self._artifact_action_failure_memory(state),
            "error_preview": str(error_text)[:500],
            "required_next_action": (
                "The planner failed immediately after a behavior-target repair packet. Do not stop and do not "
                "inspect source again. Choose one candidate_edit_records entry or valid body line and emit exactly "
                "one materializing builder command. Preserve required_prefix exactly and prefer --replace-lines for "
                "control-flow or multi-statement repairs."
            ),
            "valid_command_shapes": [
                f"{builder_command} --path {path or '<candidate-path>'} --replace-line <line> --with '<required_prefix><changed code>' > {artifact_path}",
                f"{builder_command} --path {path or '<candidate-path>'} --replace-lines <start> <end> --with '<line1>' [--with '<line2>' ...] > {artifact_path}",
            ],
        }
        return ActionDecision(
            thought="Convert inference failure after behavior-target repair context into a builder-only repair packet.",
            action=CODE_EXECUTE,
            content=self._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_inference_failure_after_behavior_target_context_read",
            proposal_metadata={
                "artifact_inference_failure_after_behavior_target_context_read": True,
                "retry_rejected_reason": "inference_failure_after_behavior_target_context",
                "artifact_candidate_path": path or artifact_path,
                "candidate_edit_records": candidate_records,
            },
        )

    def _artifact_inference_failure_after_candidate_exhausted_context_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        recent_sources = [str(step.decision_source).strip() for step in state.history[-8:]]
        if "artifact_candidate_set_exhausted_context_read" not in recent_sources:
            return None
        if not any(
            source in recent_sources
            for source in {
                "artifact_inference_failure_after_shallow_source_context_read",
                "artifact_behavior_target_repair_context_read",
                "artifact_shallow_patch_context_read",
            }
        ):
            return None
        if any(
            str(step.decision_source).strip()
            == "artifact_inference_failure_after_candidate_exhausted_context_read"
            for step in state.history[-10:]
        ):
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        candidate_records = [
            self._artifact_virtual_candidate_context_record(record)
            for record in self._artifact_placeholder_safe_candidate_records(
                list(artifact_repair_context.get("candidate_edit_records", []) or [])
            )[:12]
            if isinstance(record, dict)
        ]
        path = str(artifact_repair_context.get("preferred_source_path", "")).strip()
        if not artifact_repair_context and not candidate_records:
            return None
        recent_rejected_reasons = [
            str((step.proposal_metadata if isinstance(step.proposal_metadata, dict) else {}).get(
                "retry_rejected_reason",
                "",
            )).strip()
            for step in state.history[-8:]
        ]
        context = {
            "mode": "candidate_exhausted_after_structured_artifact_repair",
            "artifact_path": artifact_path,
            "builder_command": builder_command,
            "path": path,
            "candidate_edit_records": candidate_records,
            "valid_line_numbers_preview": artifact_repair_context.get("valid_line_numbers_preview", []),
            "source_lines_excerpt": str(artifact_repair_context.get("source_lines_excerpt", ""))[:2200],
            "fail_to_pass_function_source_excerpts": artifact_repair_context.get(
                "fail_to_pass_function_source_excerpts",
                {},
            ),
            "recent_rejected_reasons": [reason for reason in recent_rejected_reasons if reason],
            "action_failure_memory": self._artifact_action_failure_memory(state),
            "error_preview": str(error_text)[:500],
            "required_next_action": (
                "The previous structured artifact repair exhausted the candidate set, commonly because the "
                "replacement did not preserve the required indentation/prefix or targeted a stale line. Choose one "
                "candidate_edit_records entry, preserve its required_prefix exactly, and emit one materializing "
                "builder command. Prefer --replace-lines over --replace-line if the candidate changes control flow. "
                "Do not inspect source again and do not answer done."
            ),
            "valid_command_shapes": [
                f"{builder_command} --path {path or '<candidate-path>'} --replace-line <line> --with '<required_prefix><changed code>' > {artifact_path}",
                f"{builder_command} --path {path or '<candidate-path>'} --replace-lines <start> <end> --with '<line1>' [--with '<line2>' ...] > {artifact_path}",
            ],
        }
        return ActionDecision(
            thought="Convert candidate-set exhaustion after structured artifact repair into a prefix-locked builder context.",
            action=CODE_EXECUTE,
            content=self._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_inference_failure_after_candidate_exhausted_context_read",
            proposal_metadata={
                "artifact_inference_failure_after_candidate_exhausted_context_read": True,
                "retry_rejected_reason": "inference_failure_after_candidate_set_exhausted",
                "artifact_candidate_path": path or artifact_path,
                "candidate_edit_records": candidate_records,
                "recent_rejected_reasons": [reason for reason in recent_rejected_reasons if reason],
            },
        )

    def _artifact_inference_failure_after_diagnostic_context_read_decision(
        self,
        state: AgentState,
        *,
        error_text: str,
    ) -> ActionDecision | None:
        if not self._artifact_latest_repairable_failure(state):
            return None
        diagnostic_sources = {
            "artifact_candidate_set_exhausted_context_read",
            "artifact_invalid_python_off_target_context_read",
            "artifact_line_outside_anchor_context_read",
            "artifact_line_outside_anchor_range_context_read",
            "artifact_malformed_json_context_read",
            "artifact_placeholder_candidate_failed_context_read",
            "artifact_repeated_forbidden_context_read",
            "artifact_source_identical_context_read",
            "artifact_source_inspection_exhausted_context_read",
        }
        if not any(str(step.decision_source).strip() in diagnostic_sources for step in state.history[-6:]):
            return None
        if any(
            str(step.decision_source).strip() == "artifact_inference_failure_after_diagnostic_context_read"
            for step in state.history[-8:]
        ):
            return None
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        artifact_path = contract.artifact_path if contract.artifact_path else "patch.diff"
        builder_command = self._artifact_preferred_builder_command(state, contract)
        artifact_repair_context = self._artifact_retry_context_payload(
            state,
            artifact_path=artifact_path,
            builder_command=builder_command,
        )
        candidate_records = self._artifact_placeholder_safe_candidate_records(
            list(artifact_repair_context.get("candidate_edit_records", []) or [])
        )
        if not artifact_repair_context and not candidate_records:
            return None
        context = {
            "mode": "inference_failure_after_artifact_diagnostics",
            "artifact_path": artifact_path,
            "error_text": str(error_text)[:500],
            "artifact_repair_context": artifact_repair_context,
            "action_failure_memory": self._artifact_action_failure_memory(state),
            "required_next_action": (
                "The live model failed to return a usable decision after multiple artifact diagnostics. Do not "
                "inspect source again and do not emit JSON/prose. Use the artifact_repair_context to emit exactly "
                f"one {builder_command} command that writes {artifact_path}. The replacement must change behavior, "
                "not copy existing source, and must not be comment-only."
            ),
            "valid_command_shapes": [
                f"{builder_command} --path <allowed-path> --replace-line <line> --with '<replacement source line>' > {artifact_path}",
                f"{builder_command} --path <allowed-path> --replace-lines <start> <end> --with '<line1>' [--with '<line2>' ...] > {artifact_path}",
            ],
        }
        return ActionDecision(
            thought="Convert inference failure after artifact diagnostics into a bounded builder-only repair context.",
            action=CODE_EXECUTE,
            content=self._artifact_virtual_context_noop_command(
                json.dumps(context, indent=2, sort_keys=True)
            ),
            done=False,
            decision_source="artifact_inference_failure_after_diagnostic_context_read",
            proposal_metadata={
                "artifact_inference_failure_after_diagnostic_context_read": True,
                "retry_rejected_reason": "inference_failure_after_artifact_diagnostics",
                "artifact_candidate_path": str(artifact_repair_context.get("preferred_source_path", "")).strip(),
            },
        )

    def _artifact_suggested_builder_command_direct_decision(self, state: AgentState) -> ActionDecision | None:
        if self._artifact_candidate_suggestions_suppressed_by_feedback(state):
            return None
        task = state.task
        metadata = task.metadata if isinstance(task.metadata, dict) else {}
        contract = artifact_repair_contracts.contract_from_state(state)
        if contract is None:
            return None
        commands = metadata.get("artifact_suggested_builder_commands", [])
        if not isinstance(commands, list) or not commands:
            # Legacy benchmark adapters still emit this key. Keep it as an
            # adapter input, then validate through the generic artifact contract.
            commands = metadata.get("swe_suggested_patch_commands", [])
        if not isinstance(commands, list):
            return None
        attempted = {
            str(step.content).strip()
            for step in state.history
            if step.action == CODE_EXECUTE and str(step.content).strip()
        }
        for raw_command in commands:
            command = str(raw_command).strip()
            if not command or command in attempted:
                continue
            if "\n" in command or "\r" in command:
                continue
            spec = self._artifact_builder_command_spec(state, command, require_redirect=True)
            if spec is None or not spec.get("path") or not spec.get("operations"):
                continue
            if self._artifact_builder_replaces_existing_source(state, command):
                continue
            if self._artifact_builder_broad_replacement(state, command):
                continue
            if self._artifact_builder_removes_definition_header(state, command):
                continue
            if self._artifact_builder_would_produce_invalid_python(state, command):
                continue
            return ActionDecision(
                thought=(
                    "Execute the source-grounded suggested artifact repair command before asking "
                    "the model to choose a broader edit window."
                ),
                action=CODE_EXECUTE,
                content=command,
                done=False,
                decision_source="artifact_suggested_builder_command_direct",
                proposal_metadata={"artifact_suggested_builder_command": True},
            )
        return None

