    @staticmethod
    def _exact_verifier_repair_brief(state: AgentState) -> str:
        contract = artifact_repair_contracts.contract_from_state(state)
        artifact_path = contract.artifact_path if contract is not None else "patch.diff"
        builder_command = LLMDecisionPolicy._artifact_preferred_builder_command(state, contract)
        diagnoses: list[tuple[str, dict[str, object]]] = []
        active = str(state.active_subgoal).strip()
        if active:
            diagnosis = state.diagnosis_for_subgoal(active)
            if diagnosis:
                diagnoses.append((active, diagnosis))
        for goal, diagnosis in state.subgoal_diagnoses.items():
            normalized = str(goal).strip()
            if not normalized or normalized == active or not isinstance(diagnosis, dict):
                continue
            diagnoses.append((normalized, dict(diagnosis)))
        repair_items: list[str] = []
        for goal, diagnosis in diagnoses:
            path = str(diagnosis.get("path", "")).strip()
            repair_instruction = str(diagnosis.get("repair_instruction", "")).strip()
            if repair_instruction:
                if path == artifact_path:
                    summary = str(diagnosis.get("summary", "")).strip()
                    semantic_repair = ""
                    if "SWE patch removes existing Python definitions" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the invalid broad hunk; "
                            "do not use broad --replace-lines over a whole function/class or high-value window; "
                            "choose the smallest behavior-changing hunk that preserves every existing declaration line"
                        )
                    elif "SWE patch python syntax check failed" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the same invalid Python; "
                            "replace the exact bad line or narrow block with syntactically valid source at the same indentation level; "
                            "do not use single-space indentation in Python blocks; do not add indented statements at module top level "
                            "unless they remain inside an existing block"
                        )
                    elif "SWE patch leaves invalid __init__ return values" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the invalid __init__ return; "
                            "never add or keep a value-returning return statement inside __init__; choose the smallest "
                            "behavior-changing assignment/body edit or use a bare return only when early exit is required"
                        )
                    elif "SWE patch leaves invalid __init__ generators" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the generator __init__; "
                            "never add yield or yield from inside __init__; keep __init__ as ordinary object initialization "
                            "and move iterable behavior into a normal method/helper or assigned state"
                        )
                    elif "SWE patch introduces local use before assignment" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the unbound local read; "
                            "ensure every local variable is assigned before its first read and preserve the existing "
                            "initialization order with a smallest-scope statement edit"
                        )
                    elif "SWE patch changes only tests or auxiliary update artifacts" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a non-solution path; "
                            "do not edit tests, fixtures, snapshots, conftest, or update/generate helper scripts; choose "
                            "the production source file that implements the failing behavior"
                        )
                    elif "SWE patch replaces real behavior with placeholder output" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve placeholder output; "
                            "do not replace real error handling, returns, logging, or behavior with print/click output "
                            "such as 'patch applied'; make a source-grounded behavior change"
                        )
                    elif "SWE patch makes suspicious config key replacements" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a config-key substitution; "
                            "preserve existing config keys and edit values only unless the issue explicitly requires "
                            "renaming the key"
                        )
                    elif "SWE patch inserts Python-looking code into non-Python file" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a language mismatch; "
                            "use the target file's native syntax and do not insert Python expressions/imports/calls into "
                            "shell or completion files"
                        )
                    elif "SWE patch makes suspicious semantic token flips" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a bare token flip; "
                            "make a contextual data-structure change instead of swapping paired terms such as female/male"
                        )
                    elif "SWE patch removes module registration assignments" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the missing registration; "
                            "keep module-level check/rule/plugin/app registration assignments intact and move state changes "
                            "inside the relevant class or method"
                        )
                    elif "SWE patch makes suspicious unknown attribute replacements" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve an unknown attribute guess; "
                            "use attributes already visible in source context or a complete validated fallback"
                        )
                    elif "SWE patch introduces private attribute reads" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a private attribute dependency; "
                            "use public accessors or existing local data flow"
                        )
                    elif "SWE patch makes suspicious exception contract changes" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve exception/control-flow regression; "
                            "preserve existing exception propagation and validation predicates"
                        )
                    elif "SWE patch adds redundant decorated normalizations" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve redundant normalization; "
                            "do not add normalization already guaranteed by a decorator"
                        )
                    elif "SWE patch duplicates surrounding call wrappers" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a duplicated call wrapper; "
                            "replace only the inner argument/expression, or replace the complete surrounding call statement"
                        )
                    elif "SWE patch introduces unresolved name reads" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a NameError risk; "
                            "use names already bound in the local scope, parameters, imports, or module context, or add "
                            "the needed binding in the same focused patch"
                        )
                    elif "SWE patch removes production return value paths" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve the broken return contract; "
                            "replace a return expression with another return expression unless replacing a complete "
                            "control-flow block"
                        )
                    elif "SWE patch makes suspicious isolated boolean return flips" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a bare boolean guess; "
                            "avoid flipping a terminal True/False fallback and instead make a contextual condition-aware "
                            "edit anchored to the issue behavior"
                        )
                    elif "SWE patch makes suspicious Python statement-kind replacements" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve a statement-kind regression; "
                            "one-line edits must preserve the source statement kind and assignment target; if a different "
                            "kind is required, replace the complete surrounding statement or control-flow block"
                        )
                    elif "SWE patch JSON syntax check failed" in summary:
                        semantic_repair = (
                            f"; do not run {builder_command} --from-diff because it will preserve invalid JSON; "
                            "replace the complete JSON object/member span with valid JSON and preserve delimiters"
                        )
                    repair_instruction = (
                        f"{repair_instruction}; next command must create or overwrite {artifact_path} directly "
                        f"with one {builder_command} command using exact line numbers from source_lines or the high-value "
                        f"edit window; prefer --replace-line/--replace-lines and redirect to {artifact_path}; do not hand-write "
                        "unified diff hunk headers with cat/printf; do not run cat, ls, find, git, python/python3 -c, "
                        "or source inspection first"
                        f"{semantic_repair}"
                    )
                repair_items.append(repair_instruction)
                if len(repair_items) >= 3:
                    break
                continue
            if not path or diagnosis.get("expected_content") is None:
                continue
            expected = str(diagnosis.get("expected_content", ""))
            preview = str(diagnosis.get("expected_content_preview", "")).strip()
            if not preview:
                preview = json.dumps(expected)
            repair_items.append(
                f"rewrite {path} to exactly {preview}; do not paraphrase, pretty-print, add headings, or change spacing"
            )
            if len(repair_items) >= 3:
                break
        if not repair_items:
            return ""
        return " | ".join(repair_items)

    def _apply_pre_context_tolbert_route(self, state: AgentState, decision: ActionDecision) -> ActionDecision:
        route = self._tolbert_route_decision(state)
        routed = self._apply_tolbert_shadow(decision, {}, route.mode, state=state)
        return self._attach_neural_controller_shadow_metadata(state, routed)

    def _attach_neural_controller_shadow_metadata(
        self,
        state: AgentState,
        decision: ActionDecision,
    ) -> ActionDecision:
        neural_controller_advisory = self.runtime_support.neural_controller_advisory()
        neural_controller_payload = neural_controller_advisory.to_payload()
        if not neural_controller_payload.get("enabled"):
            return decision
        state_payload = {
            "task": asdict(state.task),
            "history": [
                asdict(step)
                for step in state.history[-max(1, int(self.config.payload_history_step_window)) :]
            ],
            "retrieval_plan": self._retrieval_plan(state),
            "world_model_summary": self._compact_world_model_summary(state.world_model_summary),
            "plan": self._compact_plan(state.plan),
            "state_context_chunks": list(getattr(state, "state_context_chunks", []) or [])[:6],
            "active_subgoal": self._truncate_text(state.active_subgoal),
        }
        shadow_payload = self.runtime_support.neural_controller_shadow_prediction(
            state_payload=state_payload,
        )
        compact_shadow = (
            compact_neural_controller_shadow(
                shadow_payload,
                selected_action=decision.action,
                selected_content=decision.content,
            )
            if isinstance(shadow_payload, dict) and shadow_payload
            else {}
        )
        metadata = dict(decision.proposal_metadata or {})
        metadata["neural_controller_advisory"] = {
            "mode": neural_controller_payload.get("mode", ""),
            "manifest_path": str(neural_controller_payload.get("manifest_path", "")).strip(),
            "guarded_candidate_manifest_path": str(
                neural_controller_payload.get("guarded_candidate_manifest_path", "")
            ).strip(),
            "guarded_fallback_families": list(neural_controller_payload.get("guarded_fallback_families", []) or []),
            "guarded_selector_policy": str(neural_controller_payload.get("guarded_selector_policy", "")).strip(),
            "ready": bool(neural_controller_payload.get("ready", False)),
            "surface_count": len(list(neural_controller_payload.get("surfaces", []) or [])),
            "warnings": list(neural_controller_payload.get("warnings", []) or []),
            "shadow_attempted": bool(shadow_payload),
            "shadow_generated": bool(shadow_payload.get("ready", False)) if isinstance(shadow_payload, dict) else False,
            "guarded_selected_source": str(
                shadow_payload.get("guarded", {}).get("selected_source", "")
            ).strip()
            if isinstance(shadow_payload, dict) and isinstance(shadow_payload.get("guarded", {}), dict)
            else "",
            "guarded_candidate_family": str(
                shadow_payload.get("guarded", {}).get("candidate_family", "")
            ).strip()
            if isinstance(shadow_payload, dict) and isinstance(shadow_payload.get("guarded", {}), dict)
            else "",
        }
        if compact_shadow:
            metadata["neural_controller_shadow"] = compact_shadow
        decision.proposal_metadata = metadata
        return decision

